/* Trigger structure for table `d001` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `D001_trigger_alterar_preco_D009` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'127.0.0.1' */ /*!50003 TRIGGER `D001_trigger_alterar_preco_D009` BEFORE UPDATE ON `d001` FOR EACH ROW BEGIN
  IF NEW.D001_Preco_1 > 0 OR NEW.D001_Preco_2 > 0 OR NEW.D001_Preco_3 > 0 OR NEW.D001_Preco_4 > 0 THEN
    UPDATE D009 
      LEFT JOIN D049 ON D049_Id=D009_D049_Id
      LEFT JOIN D001 ON D001_Id=D049_D001_Id
      SET
        D009_Preco_1=NEW.D001_Preco_1,
        D009_Preco_2=NEW.D001_Preco_2,
        D009_Preco_3=NEW.D001_Preco_3,
        D009_Preco_4=NEW.D001_Preco_4
    WHERE D001_Id=NEW.D001_Id;
  END IF;
END */$$


DELIMITER ;

/* Trigger structure for table `d001` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `D001_trigger_antes_alteracao` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'127.0.0.1' */ /*!50003 TRIGGER `D001_trigger_antes_alteracao` AFTER UPDATE ON `d001` FOR EACH ROW BEGIN
  IF OLD.D001_Codigo_Produto != NEW.D001_Codigo_Produto OR OLD.D001_Descricao_Produto != NEW.D001_Descricao_Produto THEN
    UPDATE T004 
    LEFT JOIN D009 ON D009_Id = T004_D009_Id
    LEFT JOIN D049 ON D049_Id = D009_D049_Id
    LEFT JOIN D001 ON D001_Id = D049_D001_Id
    LEFT JOIN T003 ON T003_Id = T004_T003_Id
    SET T004_Codigo_Produto = NEW.D001_Codigo_Produto,
    T004_Descricao_Produto = NEW.D001_Descricao_Produto
    WHERE (T004_Codigo_Produto != NEW.D001_Codigo_Produto OR T004_Descricao_Produto != NEW.D001_Descricao_Produto)
    AND T003_Flag_Status_Orcamento = 'P' AND D001_Id = NEW.D001_Id;

    UPDATE T006 
    LEFT JOIN D009 ON D009_Id = T006_D009_Id
    LEFT JOIN D049 ON D049_Id = D009_D049_Id
    LEFT JOIN D001 ON D001_Id = D049_D001_Id
    LEFT JOIN T005 ON T005_Id = T006_T005_Id
    LEFT JOIN T008 ON T008_T006_Id = T006_Id
    SET T006_Codigo_Produto = NEW.D001_Codigo_Produto,
    T006_Descricao_Produto = NEW.D001_Descricao_Produto
    WHERE (T006_Codigo_Produto != NEW.D001_Codigo_Produto OR T006_Descricao_Produto != NEW.D001_Descricao_Produto)
    AND (T008_Id IS NULL) AND D001_Id = NEW.D001_Id;

    UPDATE T219 
    LEFT JOIN D009 ON D009_Id = T219_D009_Id
    LEFT JOIN D049 ON D049_Id = D009_D049_Id
    LEFT JOIN D001 ON D001_Id = D049_D001_Id
    LEFT JOIN T218 ON T218_Id = T219_T218_Id
    SET T219_Codigo_Produto = NEW.D001_Codigo_Produto,
    T219_Descricao_Produto = NEW.D001_Descricao_Produto
    WHERE (T219_Codigo_Produto != NEW.D001_Codigo_Produto OR T219_Descricao_Produto != NEW.D001_Descricao_Produto)
    AND T218_Flag_Status_Orcamento = 'P' AND D001_Id = NEW.D001_Id;

    SET @disable_trigger = 1;
    UPDATE T225 
    LEFT JOIN D009 ON D009_Id = T225_D009_Id
    LEFT JOIN D049 ON D049_Id = D009_D049_Id
    LEFT JOIN D001 ON D001_Id = D049_D001_Id
    LEFT JOIN T224 ON T224_Id = T225_T224_Id
    SET T225_Codigo_Produto = NEW.D001_Codigo_Produto,
    T225_Descricao_Produto = NEW.D001_Descricao_Produto
    WHERE (T225_Codigo_Produto != NEW.D001_Codigo_Produto OR T225_Descricao_Produto != NEW.D001_Descricao_Produto)
    AND (T224_Flag_Status <= 0 OR T224_Flag_Status = '') AND D001_Id = NEW.D001_Id;
    SET @disable_trigger = NULL;
  END IF;
END */$$


DELIMITER ;

/* Trigger structure for table `d009` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `D009_trigger_estoque_real` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'127.0.0.1' */ /*!50003 TRIGGER `D009_trigger_estoque_real` BEFORE UPDATE ON `d009` FOR EACH ROW BEGIN
  SET NEW.D009_Quantidade_Estoque_Real=NEW.D009_Quantidade_Estoque,
      NEW.D009_Quantidade_Estoque_Loja=IFNULL((select sum(T066_Quantidade_Estoque) from T066 left join D004 on D004_Id=T066_D004_Id where T066_D009_Id=NEW.D009_Id and D004_D146_Id=2),0),
      NEW.D009_Quantidade_Estoque_Liquido=NEW.D009_Quantidade_Estoque_Real-D009_Quantidade_Pedido(NEW.D009_Id,1)-D009_Saldo_DF(NEW.D009_Id)-NEW.D009_Quantidade_Estoque_Loja,
      NEW.D009_Quantidade_Estoque_Fora=IFNULL((SELECT SUM(D009_Quantidade_Estoque_Loja+D009_Quantidade_Estoque_Liquido) FROM D009 WHERE D009_D049_Id=NEW.D009_D049_Id AND D009_Id!=NEW.D009_Id),0);
END */$$


DELIMITER ;

/* Trigger structure for table `d085` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `D085_atualiza_D024` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'e000'@'%' */ /*!50003 TRIGGER `D085_atualiza_D024` AFTER INSERT ON `d085` FOR EACH ROW BEGIN
    UPDATE D024 SET D024_D085_Id = NEW.D085_Id WHERE D024_Id=NEW.D085_D024_Id;
    UPDATE D024 SET D024_Flag_Comercial = 'A', D024_C007_Vendedor_Interno=NEW.D085_C007_Id, D024_Classe='', D024_D021_Id=NEW.D085_D021_Id, D024_Data_Ativo=curdate() WHERE D024_Id=NEW.D085_D024_Id and D024_Flag_Comercial='I';
END */$$


DELIMITER ;

/* Trigger structure for table `t001` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `T001_trigger_atualiza_estoque` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'127.0.0.1' */ /*!50003 TRIGGER `T001_trigger_atualiza_estoque` BEFORE INSERT ON `t001` FOR EACH ROW BEGIN

  DECLARE xD009_Saldo_Atual DECIMAL(20,3);

  DECLARE xCount INT;

  UPDATE D009 SET D009_Quantidade_Estoque=IF(NEW.T001_Flag_Operacao='S',D009_Quantidade_Estoque-NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='E',D009_Quantidade_Estoque+NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='B',NEW.T001_Quantidade,D009_Quantidade_Estoque))),

                  D009_Quantidade_Estoque_Real=D009_Quantidade_Estoque-D009_Quantidade_Pedido(D009_Id,2)-D009_Quantidade_Pendencia(D009_Id),

                  D009_Quantidade_Estoque_Liquido=D009_Quantidade_Estoque_Real-D009_Quantidade_Pedido(D009_Id,1),

                  D009_Valor_Custo_Unitario=IF(NEW.T001_Flag_Atualiza_Custo='S',NEW.T001_Valor_Custo_Unitario,D009_Valor_Custo_Unitario),

                  D009_Valor_Custo_Medio_Unitario=IF(NEW.T001_Flag_Atualiza_Custo='S',NEW.T001_Valor_Custo_Medio_Unitario,D009_Valor_Custo_Medio_Unitario)

   WHERE D009_Id=NEW.T001_D009_Id;

  SELECT D009_Quantidade_Estoque INTO xD009_Saldo_Atual FROM D009 WHERE D009_Id=NEW.T001_D009_Id;

  IF xD009_Saldo_Atual IS NULL THEN

    SET xD009_Saldo_Atual=0;

  END IF;

  SET NEW.T001_Quantidade_Saldo=xD009_Saldo_Atual;

  SET NEW.T001_Data_Hora_Insercao=NOW();

  -- o T066 será atualizar na trigger da tabela T186 (T186_T001_Id)

  -- -- se tiver T185 é sistema de estoque novo (multi-locação), o T066 será atualizar na trigger da tabela T186 (T186_T001_Id)

  -- SELECT COUNT(*) INTO xCount FROM T185 WHERE T185_T006_Id = NEW.T001_T006_Id;

  -- IF xCount IS NULL OR xCount = 0 THEN

  --  -- senão será sempre utilizada a primeira locação (código antigo)

  --  UPDATE T066 SET T066_Quantidade_Estoque=IF(NEW.T001_Flag_Operacao='S',T066_Quantidade_Estoque-NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='E',T066_Quantidade_Estoque+NEW.T001_Quantidade,IF(NEW.T001_Flag_Operacao='B',NEW.T001_Quantidade,T066_Quantidade_Estoque))) WHERE T066_Id=NEW.T001_T066_Id;

  -- END IF;

END */$$


DELIMITER ;

