                  T002_Valor_Desconto=xT020_Valor_Desconto,
                  T002_Valor_Total=T002_Valor_Duplicata+xT020_Valor_Juros-xT020_Valor_Desconto
         WHERE T002_Id=NEW.T020_T002_Id;
END */$$


