/* Function  structure for function  `D009_Quantidade_OC` */

/*!50003 DROP FUNCTION IF EXISTS `D009_Quantidade_OC` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `D009_Quantidade_OC`(xD009_Id INT(11)) RETURNS decimal(10,3)
BEGIN
   DECLARE xQuantidade decimal(10,3);
   DECLARE xNacImp varchar(1);
      SELECT D049_Flag_Nacional_Importado
        INTO xNacImp
        FROM D009
   LEFT JOIN D049 ON D049_Id=D009_D049_Id
       WHERE D009_Id=xD009_Id;
 
   IF xNacImp='I' THEN
        SELECT sum(T053_Quantidade-ifnull((select ifnull(sum(T055_Quantidade),0) from T055 left join T054 on T054_Id=T055_T054_Id where T055_T053_Id=T053_Id and T054_Data_Transferencia_Estoque!='0000-00-00 00:00:00'),0))
          INTO xQuantidade 
          FROM T053 
     LEFT JOIN T052 ON T052_Id=T053_T052_Id
         WHERE T052_Data_Emissao>=DATE_SUB(current_date(), interval 6 month)
           AND T053_D009_Id=xD009_Id
           AND T053_Flag_Cancelada!='S'
           AND T053_Flag_Cancelada!='S';
   ELSE 
        SELECT sum(T012_Quantidade-ifnull((select ifnull(sum(T014_Quantidade),0) from T014 left join T013 on T013_Id=T014_T013_Id where T014_T012_Id=T012_Id and T013_Flag_Travar_Nota='S' and T013_Flag_Cancelada!='S'),0))
          INTO xQuantidade 
          FROM T012 
     LEFT JOIN T011 ON T011_Id=T012_T011_Id
         WHERE T011_Data_Emissao>=DATE_SUB(current_date(), interval 6 month)
           AND T012_D009_Id=xD009_Id
           AND T012_Flag_Cancelada!='S'
           AND T011_Flag_Cancelada!='S';
   END IF;
   IF xQuantidade IS NULL or xQuantidade<0 THEN
      SET xQuantidade = 0;
   END IF;
   RETURN xQuantidade;
END */$$
DELIMITER ;

/* Function  structure for function  `D009_Quantidade_OC_3` */

/*!50003 DROP FUNCTION IF EXISTS `D009_Quantidade_OC_3` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `D009_Quantidade_OC_3`(xD009_Id int(10), xT075_Id int(10)) RETURNS varchar(10) CHARSET utf8
BEGIN



     DECLARE xQuantidade_Pendente DECIMAL(10,3);

     DECLARE xQuantidade_Pendente_OC DECIMAL(10,3);

     DECLARE xQuantidade_Pendente_DI DECIMAL(10,3);



     SELECT sum(T225_Quantidade-(select if(ifnull(sum(T014_Quantidade),0) > T225_Quantidade, T225_Quantidade, ifnull(sum(T014_Quantidade),0)) from T014 left join T013 on T013_Id=T014_T013_Id where T014_T225_Id=T225_Id and T013_Flag_Travar_Nota='S' and T013_Flag_Estoque_Finalizado='S' and T013_Flag_Cancelada!='S'))

       INTO xQuantidade_Pendente_OC

       FROM T225

  LEFT JOIN T224 on T224_Id=T225_T224_Id

      WHERE T225_D009_Id=xD009_Id

        AND T225_Flag_Cancelada!='S'

        AND T224_Flag_Cancelada!='S'

        AND T224_Flag_Status!='12'

        AND T224_Flag_Status!='11'

        AND T224_Flag_Status!='2';



      IF xQuantidade_Pendente_OC IS NULL or xQuantidade_Pendente_OC<0 THEN

        SET xQuantidade_Pendente_OC = 0;

      END IF;



      SELECT SUM(T055_Quantidade-(SELECT IFNULL(SUM(T006_Quantidade),0) FROM T006 WHERE T006_T075_Id=T075_Id AND T006_D009_Id=D009_Id AND T006_Flag_Status!='3')) 

        INTO xQuantidade_Pendente_DI

        FROM T055

   LEFT JOIN T075 ON T075_Id=T055_T075_Id

   LEFT JOIN D009 ON D009_Id=T055_D009_Id

   LEFT JOIN C031 ON C031_C004_Id=D009_C004_Id AND C031_Campo = 'diasMedioPrazo'

       WHERE T055_D009_Id=xD009_Id

         AND IFNULL(T075_Data_Estoque,'0000-00-00')='0000-00-00' 

         AND T075_Data_Previsao>0 

         AND T075_Data_Previsao<=DATE(DATE_ADD(NOW(), INTERVAL C031_Valor DAY))

         AND T075_Flag_MP = 1;



      IF xQuantidade_Pendente_DI IS NULL or xQuantidade_Pendente_DI<0 THEN

        SET xQuantidade_Pendente_DI = 0;

      END IF;



      SET xQuantidade_Pendente = xQuantidade_Pendente_OC + xQuantidade_Pendente_DI;

      RETURN xQuantidade_Pendente;



END */$$
DELIMITER ;

/* Function  structure for function  `D009_Quantidade_OS` */

