/* Function  structure for function  `T004_Ultimo_Preco` */

/*!50003 DROP FUNCTION IF EXISTS `T004_Ultimo_Preco` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `T004_Ultimo_Preco`(xD001_Id INT(11), xD024_Id INT(11), xT003_Id INT(11), xTipo varchar(1)) RETURNS varchar(94) CHARSET latin1
BEGIN
    DECLARE xRetorno VARCHAR(94);
    if xTipo=2 then
       SELECT concat(concat('R$ ',format(T008_Valor_Preco_Unitario,2),' - Qte: ',format(T008_Quantidade,2),' - ',date_format(T007_Data_Emissao,'%d/%m/%Y'),' ( ',datediff(current_date(),T007_Data_Emissao),' ) ',' - ',left(D024_Nome_Empresa,15)),' - NF: ',T007_Numero_Nota_Fiscal,' - ',C007_Primeiro_Nome)
         INTO xRetorno
         FROM T008
    LEFT JOIN T007 on T007_Id=T008_T007_Id
    LEFT JOIN D009 on D009_Id=T008_D009_Id
    LEFT JOIN D049 on D049_Id=D009_D049_Id
    LEFT JOIN D024 on D024_Id=T007_D024_Id
    LEFT JOIN C007 on C007_Id=T007_C007_Id_Vendedor_Interno
        WHERE T007_D024_Id=xD024_Id
          AND D009_D001_Id=xD001_Id
     ORDER BY T007_Data_Emissao desc
        LIMIT 0,1;
    else
       SELECT concat(concat('R$ ',format(T004_Valor_Preco_Unitario,2),' - Qte: ',format(T004_Quantidade,2),' - ',date_format(T003_Data_Emissao,'%d/%m/%Y'),' ( ',datediff(current_date(),T003_Data_Emissao),' ) ',' - ',left(D024_Nome_Empresa,15)),' - Orc: ',format(T003_Id,0),' - ',C007_Primeiro_Nome)
         INTO xRetorno
         FROM T004
    LEFT JOIN T003 on T003_Id=T004_T003_Id
    LEFT JOIN D009 on D009_Id=T004_D009_Id
    LEFT JOIN D049 on D049_Id=D009_D049_Id
    LEFT JOIN D024 on D024_Id=T003_D024_Id
    LEFT JOIN C007 on C007_Id=T003_C007_Id_Vendedor_Interno
        WHERE T003_D024_Id=xD024_Id
          AND D009_D001_Id=xD001_Id
          AND T003_Id!=xT003_Id
          AND T004_Valor_Preco_Unitario>0
     ORDER BY T003_Data_Emissao desc
        LIMIT 0,1;
    end if;
    RETURN xRetorno;
END */$$
DELIMITER ;

