/* Function  structure for function  `T007_Primeira_Ultima_Compra` */

/*!50003 DROP FUNCTION IF EXISTS `T007_Primeira_Ultima_Compra` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `T007_Primeira_Ultima_Compra`(xTipo int(1), xD024_Id integer) RETURNS varchar(10) CHARSET latin1
BEGIN
  Declare xRetorno VARCHAR(10);


  if xTipo=1 then
    select T007_Data_Emissao
    into xRetorno
                     from T007
                left join D006 on D006_Id=T007_D006_Id
                    where T007_D024_Id = xD024_Id
                      and D006_Flag_Entrada_Saida='S'
                      and T007_Flag_Cancelada <> 'S'
                      and D006_Flag_Gera_Contas='R'
                      and D006_Flag_Devolucao<>'S'
                      and D006_Flag_Venda_Compra_Outros = 'V'
                 order by T007_Data_Emissao asc
    limit 1;
    IF xRetorno is null THEN
      SET xRetorno = '0000-00-00';
    END if;
  elseif xTipo=2 then
    select T007_Data_Emissao
    into xRetorno
                     from T007
                left join D006 on D006_Id=T007_D006_Id
                    where T007_D024_Id = xD024_Id
                      and D006_Flag_Entrada_Saida='S'
                      and T007_Flag_Cancelada <> 'S'
                      and D006_Flag_Gera_Contas='R'
                      and D006_Flag_Devolucao<>'S'
                      and D006_Flag_Venda_Compra_Outros = 'V'
                 order by T007_Data_Emissao desc
    limit 1;
    IF xRetorno is null THEN
      SET xRetorno = '0000-00-00';
    END if;
  elseif xTipo=3 then
    select T007_C004_Id
    into xRetorno
                     from T007
                left join D006 on D006_Id=T007_D006_Id
                    where T007_D024_Id = xD024_Id
                      and D006_Flag_Entrada_Saida='S'
                      and T007_Flag_Cancelada <> 'S'
                      and D006_Flag_Gera_Contas='R'
                      and D006_Flag_Devolucao<>'S'
                      and D006_Flag_Venda_Compra_Outros = 'V'
                 order by T007_Data_Emissao desc
    limit 1;
    IF xRetorno is null THEN
      SET xRetorno = '0';
    END if;
  end if;

     Return xRetorno;
END */$$
DELIMITER ;

/* Function  structure for function  `T008_Quantidade_Falta_Lancar` */

/*!50003 DROP FUNCTION IF EXISTS `T008_Quantidade_Falta_Lancar` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T008_Quantidade_Falta_Lancar`(xT008_Id INT(11)) RETURNS decimal(15,3)
BEGIN

     DECLARE xQuantidade_Falta_Lancar DECIMAL(15,3);

     SELECT IFNULL(T008_Quantidade,0)-IFNULL(SUM(IF(T013_Flag_Cancelada!='S',T014_Quantidade,0)),0)

       INTO xQuantidade_Falta_Lancar

       FROM T008

  LEFT JOIN T014 on T014_T008_Id=T008_Id

  LEFT JOIN T013 on T013_Id=T014_T013_Id

      WHERE T008_Id=xT008_Id;

     IF xQuantidade_Falta_Lancar IS NULL or xQuantidade_Falta_Lancar<0 THEN

        SET xQuantidade_Falta_Lancar = 0;

     END IF;

     RETURN xQuantidade_Falta_Lancar;

END */$$
DELIMITER ;

/* Function  structure for function  `T008_ST_Cupom` */

/*!50003 DROP FUNCTION IF EXISTS `T008_ST_Cupom` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `T008_ST_Cupom`(xT008_Id int(10)) RETURNS char(2) CHARSET latin1
BEGIN
    DECLARE xRetorno CHAR(2) default NULL;
    DECLARE xAliquota_ICMS decimal(5,2) default 0;
  DECLARE xFlag_ST char(1) default 'N';
  DECLARE xD059_Id int(10) default 0;    
    
    select T008_Aliquota_ICMS,
         T008_Flag_ST,
         T008_D059_Id
      into xAliquota_ICMS,
           xFlag_ST,
           xD059_Id    
      from T008 
      left join D006 on D006_Id=T008_D006_Id
     where T008_Id=xT008_Id;
    
    
     IF xFlag_ST='S' THEN
     
        select D090_Codigo_Impressora
          into xRetorno
      from D090
       where D090_Flag_ST=xFlag_ST;
       
     ELSEIF xAliquota_ICMS>0 THEN
     
        select D090_Codigo_Impressora
          into xRetorno       
      from D090
       where D090_Aliquota_Icms=xAliquota_ICMS;
       
   ELSEIF xAliquota_ICMS=0 THEN 
   
        select D090_Codigo_Impressora
          into xRetorno       
      from D090
       where D090_D059_Id=xD059_Id;
       
     END IF;   
     
   IF xRetorno IS NULL THEN
      SET xRetorno='NN'; 
     END IF;        
     
    RETURN xRetorno;
END */$$
DELIMITER ;

/* Function  structure for function  `T012_Quantidade_Falta_Lancar` */

/*!50003 DROP FUNCTION IF EXISTS `T012_Quantidade_Falta_Lancar` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `T012_Quantidade_Falta_Lancar`(xT012_Id INT(11),xT086_Id INT(11)) RETURNS decimal(10,3)
BEGIN
     DECLARE xQuantidade_Falta_Lancar DECIMAL(10,3);
     SELECT IFNULL(T012_Quantidade,0)-IFNULL(SUM(T014_Quantidade),0)-IFNULL(SUM(T086_Quantidade),0)
       INTO xQuantidade_Falta_Lancar
       FROM T012
  LEFT JOIN T086 on T086_T012_Id=T012_Id and T086_Id!=xT086_Id
  LEFT JOIN T014 on T014_T012_Id=T012_Id
  LEFT JOIN T013 on T013_Id=T014_T013_Id
  LEFT JOIN T011 on T011_Id=T012_T011_Id
      WHERE T012_Id=xT012_Id
        AND T011_Flag_Cancelada!='S'
        AND T012_Flag_Cancelada!='S'
        AND T013_Flag_Cancelada!='S';
     IF xQuantidade_Falta_Lancar IS NULL or xQuantidade_Falta_Lancar<0 THEN
        SET xQuantidade_Falta_Lancar = 0;
     END IF;
     RETURN xQuantidade_Falta_Lancar;
END */$$
DELIMITER ;

/* Function  structure for function  `T012_Quantidade_Pendente` */

/*!50003 DROP FUNCTION IF EXISTS `T012_Quantidade_Pendente` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` FUNCTION `T012_Quantidade_Pendente`(xT012_Id INT(11)) RETURNS decimal(10,3)
BEGIN
     DECLARE xQuantidade_Pendente DECIMAL(10,3);
     SELECT IFNULL(T012_Quantidade,0)-IFNULL(SUM(T014_Quantidade),0)
       INTO xQuantidade_Pendente
       FROM T012
  LEFT JOIN T011 on T011_Id=T012_T011_Id
  LEFT JOIN T014 on T014_T012_Id=T012_Id
  LEFT JOIN T013 on T013_Id=T014_T013_Id
      WHERE T014_T012_Id=xT012_Id
        AND T013_Flag_Travar_Nota='S'
        AND T013_Flag_Cancelada!='S'
        AND T012_Flag_Cancelada!='S'
        and T011_Flag_Cancelada!='S';
     IF xQuantidade_Pendente IS NULL or xQuantidade_Pendente<0 THEN
        SET xQuantidade_Pendente = 0;
     END IF;
     RETURN xQuantidade_Pendente;
END */$$
DELIMITER ;

