/* Function  structure for function  `T218_IPV_Medio` */

/*!50003 DROP FUNCTION IF EXISTS `T218_IPV_Medio` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T218_IPV_Medio`(xT218_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xTotal_IPV DECIMAL(10,4);

    DECLARE xTotal_Itens INT(10);

    DECLARE xIPV_Medio DECIMAL(10,4);

    IF xTipo=1 THEN

       SELECT SUM(T219_Valor_Total_Preco)/SUM(T219_Valor_Total_Custo),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T219

    LEFT JOIN T218 on T218_Id=T219_T218_Id

    LEFT JOIN D009 on D009_Id=T219_D009_Id

        WHERE T219_T218_Id=xT218_Id

          AND T219_Quantidade>0

          AND T219_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

          AND T219_Id NOT IN (SELECT T219_Id FROM T225 LEFT JOIN T219 ON T219_Id=T225_T219_Id WHERE T219_T218_Id=xT218_Id)

        GROUP BY T219_T218_Id;

    ELSEIF xTipo=2 THEN

       SELECT SUM(T219_Valor_Total_Preco_Confirmado)/SUM(T219_Valor_Total_Custo_Confirmado),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T219

    LEFT JOIN T218 on T218_Id=T219_T218_Id

    LEFT JOIN D009 on D009_Id=T219_D009_Id

        WHERE T219_T218_Id=xT218_Id

          AND T219_Quantidade_Confirmada>0

          AND T219_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

          AND T219_Id NOT IN (SELECT T219_Id FROM T225 LEFT JOIN T219 ON T219_Id=T225_T219_Id WHERE T219_T218_Id=xT218_Id)

        GROUP BY T219_T218_Id;

    ELSEIF xTipo=3 THEN

       SELECT SUM(T219_Valor_Total_Preco)/SUM(T219_Valor_Total_Custo),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T219

    LEFT JOIN T218 on T218_Id=T219_T218_Id

    LEFT JOIN D009 on D009_Id=T219_D009_Id

        WHERE T219_T218_Id=xT218_Id

          AND T219_Quantidade>0

          AND T219_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

        GROUP BY T219_T218_Id;

    ELSEIF xTipo=4 THEN

       SELECT SUM(T219_Valor_Total_Preco_Confirmado)/SUM(T219_Valor_Total_Custo_Confirmado),

              SUM(1)

         INTO xTotal_IPV,

              xTotal_Itens

         FROM T219

    LEFT JOIN T218 on T218_Id=T219_T218_Id

    LEFT JOIN D009 on D009_Id=T219_D009_Id

        WHERE T219_T218_Id=xT218_Id

          AND T219_Quantidade_Confirmada>0

          AND T219_Flag_Cancelado!='S'

          AND ifnull(D009_Flag_Preco_Tabelado,'N')!='S'

        GROUP BY T219_T218_Id;

    END IF;

    IF xTotal_Itens>0 THEN

       SET xIPV_Medio=xTotal_IPV;

    ELSE

       SET xIPV_Medio=0;

    END IF;

    RETURN xIPV_Medio;

END */$$
DELIMITER ;

/* Function  structure for function  `T224_IPV_Medio` */

/*!50003 DROP FUNCTION IF EXISTS `T224_IPV_Medio` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T224_IPV_Medio`(xT224_Id int(11),xTipo int(1)) RETURNS decimal(10,4)
BEGIN

    DECLARE xTotal_IPV DECIMAL(10,4);

    DECLARE xTotal_Itens INT(10);

    DECLARE xIPV_Medio DECIMAL(10,4);

    SELECT SUM(T225_Valor_Total_Preco)/sum(T225_Valor_Total_Custo),

           SUM(1)

      INTO xTotal_IPV,

           xTotal_Itens

           FROM T225

      LEFT JOIN T224 ON T224_Id=T225_T224_Id

           WHERE T225_T224_Id=xT224_Id

            GROUP BY T225_T224_Id;

    IF xTotal_Itens>0 THEN

       SET xIPV_Medio=xTotal_IPV;

    ELSE

       SET xIPV_Medio=0;

    END IF;

    RETURN xIPV_Medio;

END */$$
DELIMITER ;

/* Function  structure for function  `T224_Prazos` */

/*!50003 DROP FUNCTION IF EXISTS `T224_Prazos` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T224_Prazos`(xT224_Id int(11)) RETURNS varchar(255) CHARSET latin1
BEGIN

    DECLARE xTotal_Parcelas INT(2) DEFAULT 0;

    DECLARE xTotal_Prazos VARCHAR(255);

    DECLARE xRetorno VARCHAR(255) DEFAULT 'A COMBINAR';

    DECLARE xPrazos_Dias INT(5) DEFAULT 0;

    DECLARE xNumero_Parcela  INT(3) DEFAULT 0;

    DECLARE xFlag_Gera_Contas VARCHAR(1) DEFAULT ' ';

    SELECT D006_Flag_Gera_Contas

      INTO xFlag_Gera_Contas

      FROM T224

      LEFT JOIN D006 ON D006_Id=T224_D006_Id

     WHERE T224_Id=xT224_Id;

    IF xFlag_Gera_Contas!='N' THEN

       SELECT SUM(1),

              CONCAT(GROUP_CONCAT(T226_Prazos_Dias SEPARATOR '/'),' dias'),

              T226_Prazos_Dias,

              T226_Numero_Parcela

         INTO xTotal_Parcelas,

              xTotal_Prazos,

              xPrazos_Dias,

              xNumero_Parcela

         FROM T226

        WHERE T226_T224_Id=xT224_Id

        GROUP BY T226_T224_Id;



        IF xTotal_Parcelas > 0 THEN

           IF xTotal_Parcelas = 1 AND xPrazos_Dias = 0 THEN

              SET xRetorno = 'A VISTA';

           ELSE

              SET xRetorno = xTotal_Prazos;

           END IF;

        ELSE

           SET xRetorno = '';

        END IF;

    END IF;

    RETURN xRetorno;

END */$$
DELIMITER ;

/* Function  structure for function  `T224_Status_Pedido` */

/*!50003 DROP FUNCTION IF EXISTS `T224_Status_Pedido` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T224_Status_Pedido`(xStatus int(2), xT224_Id INT(11)) RETURNS varchar(30) CHARSET latin1
BEGIN

    DECLARE xDescricao VARCHAR(25);

    DECLARE xPercentualRecebido INT;

    

    SET xDescricao = '';

    

    IF xStatus=0 OR xStatus='' THEN

        SET xDescricao = 'Pendente';

    END IF;

    IF xStatus=1 THEN

        SET xDescricao = 'Analise';

    END IF;

    IF xStatus=2 THEN

        SET xDescricao = 'NEGADO';

    END IF;

    IF xStatus=3 THEN

        SET xDescricao = 'APROVADO';

    END IF;

    IF xStatus=4 THEN

        SET xDescricao = 'Financeiro';

    END IF;

    IF xStatus=5 THEN

        SET xDescricao = 'Aguard.Coleta';

    END IF;

    IF xStatus=6 THEN

        SET xDescricao = 'Coletando';

    END IF;

    IF xStatus=7 THEN

        SET xDescricao = 'Coletado';

    END IF;

    IF xStatus=8 THEN

        SET xDescricao = 'Aguard.Mercadoria';

    END IF;

    IF xStatus=9 THEN

        SELECT

            (SUM(DISTINCT CONCAT(IFNULL(T014_Quantidade,'0.00000'),T014_Id))/SUM(DISTINCT CONCAT(T225_Quantidade,T225_Id)))*100

        INTO 

            xPercentualRecebido

        FROM T224 

        LEFT JOIN T225 ON T225_T224_Id = T224_Id AND T225_Flag_Cancelada != 'S'

        LEFT JOIN T014 ON T014_T225_Id = T225_Id AND T014_Flag_Cancelada != 'S' AND ifnull((SELECT T013_Flag_Estoque_Finalizado FROM T013 WHERE T014_T013_Id = T013_Id),'N') = 'S'

        LEFT JOIN T013 ON T014_T013_Id = T013_Id AND T013_Flag_Travar_Nota = 'S' AND T013_Flag_Cancelada != 'S' AND T013_Flag_Estoque_Finalizado = 'S'

        WHERE T224_Id = xT224_Id;



        SET xDescricao = CONCAT('Recebido ',IFNULL(xPercentualRecebido,0),'%');

    END IF;

    IF xStatus=10 THEN

        SET xDescricao = 'Finalizado';

    END IF;

    IF xStatus=11 THEN

        SET xDescricao = 'Cancelado';

    END IF;

    IF xStatus=12 THEN

        SET xDescricao = 'Vencido';

    END IF;

    

    IF xDescricao = '' THEN

        SET xDescricao = ' - ';

    END IF;

    RETURN xDescricao;

END */$$
DELIMITER ;

/* Function  structure for function  `T225_Quantidade_Pendente_3` */

/*!50003 DROP FUNCTION IF EXISTS `T225_Quantidade_Pendente_3` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `T225_Quantidade_Pendente_3`(xT225_Id INT(11)) RETURNS decimal(10,3)
BEGIN

     DECLARE xQuantidade_Pendente DECIMAL(10,3);

     SELECT IFNULL(T225_Quantidade,0)-IFNULL(SUM(if(T013_Flag_Travar_Nota='S' and T013_Flag_Estoque_Finalizado='S',T014_Quantidade,0)),0)

       INTO xQuantidade_Pendente

       FROM T225

  LEFT JOIN T224 on T224_Id=T225_T224_Id

  LEFT JOIN T014 on T014_T225_Id=T225_Id

  LEFT JOIN T013 on T013_Id=T014_T013_Id

      WHERE T225_Id=xT225_Id

        AND ifnull(T013_Flag_Cancelada,'N')!='S'

        AND ifnull(T014_Flag_Cancelada,'N')!='S'

        AND T225_Flag_Cancelada!='S'

        and T224_Flag_Cancelada!='S'

        and T224_Flag_Status!=11;

     IF xQuantidade_Pendente IS NULL or xQuantidade_Pendente<0 THEN

        SET xQuantidade_Pendente = 0;

     END IF;

     RETURN xQuantidade_Pendente;

END */$$
DELIMITER ;

/* Procedure structure for procedure `D024_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `D024_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `D024_Gravar_Totalizacao`(xD024_Id int(11))
BEGIN
    DECLARE xValor_Credito_Antecipado DECIMAL(14,2);
    DECLARE xValor_Atual DECIMAL(14,2) DEFAULT '0.00';
    DECLARE xValor_Saldo_Atual DECIMAL(14,2) DEFAULT '0.00';
    DECLARE xValor_Saldo_Credito_Antecipado DECIMAL(14,2) DEFAULT '0.00';
  DECLARE xValor_Saldo_Credito_Troca DECIMAL(14,2) DEFAULT '0.00';
  DECLARE xValor_Abatimento_Credito_Antecipado DECIMAL(14,2);
  DECLARE xValor_Credito_Troca DECIMAL(14,2);
  DECLARE xValor_Abatimento_Credito_Troca DECIMAL(14,2);
    DECLARE done int DEFAULT FALSE;
    DECLARE xFlag_Credito_Antecipado char(1);
    DECLARE xT000_Id int(11);
    DECLARE xTipo_Titulo char(1);

    DECLARE xCursor CURSOR FOR 
    (SELECT T002_Id, SUM(ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)), D027_Flag_Credito_Antecipado, T002_Valor_Saldo_Credito, 'R'
    FROM T002 
    LEFT JOIN D027 ON D027_Id = T002_D027_Id
    WHERE T002_D024_Id = xD024_Id AND IFNULL(D027_Flag_Credito_Antecipado,'') != ''
    GROUP BY T002_Id ORDER BY T002_Id, T002_Data_Emissao)
    UNION
    (SELECT T015_Id, SUM(ifnull(T015_Valor_Duplicata,0)+ifnull(T015_Valor_Juros,0)-ifnull(T015_Valor_Desconto,0)), D031_Flag_Credito_Antecipado, T015_Valor_Saldo_Credito, 'P'
    FROM T015 
    LEFT JOIN D031 ON D031_Id = T015_D031_Id
    WHERE T015_D024_Id = xD024_Id AND IFNULL(D031_Flag_Credito_Antecipado,'') != ''
    GROUP BY T015_Id ORDER BY T015_Id, T015_Data_Emissao);

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    SET xValor_Saldo_Credito_Antecipado = 0;
    SET xValor_Saldo_Credito_Troca = 0;
    OPEN xCursor;

    the_loop: LOOP

        FETCH xCursor INTO xT000_Id, xValor_Atual, xFlag_Credito_Antecipado, xValor_Saldo_Atual, xTipo_Titulo;
        IF done THEN
          LEAVE the_loop;
        END IF;

        IF xFlag_Credito_Antecipado = '1' THEN
            SET xValor_Saldo_Credito_Antecipado = xValor_Saldo_Credito_Antecipado + xValor_Atual;
        ELSEIF xFlag_Credito_Antecipado = '2' THEN
            SET xValor_Saldo_Credito_Troca = xValor_Saldo_Credito_Troca + xValor_Atual;
        ELSEIF xFlag_Credito_Antecipado = '3' THEN
            SET xValor_Saldo_Credito_Antecipado = xValor_Saldo_Credito_Antecipado - xValor_Atual;
        ELSEIF xFlag_Credito_Antecipado = '4' THEN
            SET xValor_Saldo_Credito_Troca = xValor_Saldo_Credito_Troca - xValor_Atual;
        END IF;

        IF xTipo_Titulo = 'R' THEN
            IF (xFlag_Credito_Antecipado = '1' OR xFlag_Credito_Antecipado = '3') AND xValor_Saldo_Credito_Antecipado != xValor_Saldo_Atual THEN
                UPDATE T002 SET T002_Valor_Saldo_Credito = xValor_Saldo_Credito_Antecipado WHERE T002_Id = xT000_Id;
            ELSEIF (xFlag_Credito_Antecipado = '2' OR xFlag_Credito_Antecipado = '4') AND xValor_Saldo_Credito_Troca != xValor_Saldo_Atual THEN
                UPDATE T002 SET T002_Valor_Saldo_Credito = xValor_Saldo_Credito_Troca WHERE T002_Id = xT000_Id;
            END IF;
        ELSEIF xTipo_Titulo = 'P' THEN
            IF (xFlag_Credito_Antecipado = '1' OR xFlag_Credito_Antecipado = '3') AND xValor_Saldo_Credito_Antecipado != xValor_Saldo_Atual THEN
                UPDATE T015 SET T015_Valor_Saldo_Credito = xValor_Saldo_Credito_Antecipado WHERE T015_Id = xT000_Id;
            ELSEIF (xFlag_Credito_Antecipado = '2' OR xFlag_Credito_Antecipado = '4') AND xValor_Saldo_Credito_Troca != xValor_Saldo_Atual THEN
                UPDATE T015 SET T015_Valor_Saldo_Credito = xValor_Saldo_Credito_Troca WHERE T015_Id = xT000_Id;
            END IF;
        END IF;

    END LOOP the_loop;
 
    CLOSE xCursor;        

    UPDATE D024 SET D024_Valor_Credito_Antecipado = xValor_Saldo_Credito_Antecipado, D024_Valor_Credito_Troca = xValor_Saldo_Credito_Troca WHERE D024_Id = xD024_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `D069_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `D069_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `D069_Gravar_Totalizacao`(xD069_Id int(11))
BEGIN
        DECLARE xD070_Id int;
        DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;
        DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Despesa_Recebida DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Despesas_Acessorias_Recebida DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;
        DECLARE xMultiplicador_Frete_Recebida DECIMAL(20,10) DEFAULT 0;
        DECLARE xFlag_Revenda_Consumidor VARCHAR(1);
        DECLARE xFlag_Devolucao VARCHAR(1);
        DECLARE xFlag_Tipo_Devolucao VARCHAR(10);
        DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;
        DECLARE xValor_Total_Frete_Recebida DECIMAL(19,2) DEFAULT 0;
        DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;
        DECLARE xValor_Total_Despesas_Acessorias_Recebida DECIMAL(10,2) DEFAULT 0;
        DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;
        DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;
        DECLARE xValor_Total_Desconto_Recebida DECIMAL(10,2) DEFAULT 0;
        DECLARE xFlag_ST VARCHAR(3);
        DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);
        DECLARE xAliquota_ICMS_1 DECIMAL(5,2);
        DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';
        DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';
        DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';
        DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';
        DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';
        DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';
        DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';
        DECLARE xD059_Codigo_ST varchar(3);
        DECLARE xD049_Flag_Nacional_Importado varchar(1);

        DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';
        DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

        SELECT D069_D070_Id,
                     D006_Flag_Venda_Compra_Outros,
                     D049_Flag_Nacional_Importado,
                     D006_Flag_Somar_IPI_Base_ICMS,
                     D006_Flag_Somar_Despesas_Base_IPI,
                     D006_Flag_Somar_Despesas_Base_ST,
                     D006_Flag_Forma_Calculo_COFINS,
                     D006_Flag_Forma_Calculo_PIS,
                     D069_Percentual_Desconto_Bruto/100
            INTO xD070_Id,
                     xFlag_Venda_Compra_Outros,
                     xD049_Flag_Nacional_Importado,
                     xD006_Flag_Somar_IPI_Base_ICMS,
                     xD006_Flag_Somar_Despesas_Base_IPI,
                     xD006_Flag_Somar_Despesas_Base_ST,
                     xD006_Flag_Forma_Calculo_COFINS,
                     xD006_Flag_Forma_Calculo_PIS,
                     xPercentual_Desconto_Bruto
            FROM D069
            LEFT JOIN D070 ON D070_Id=D069_D070_Id
            LEFT JOIN D006 ON D006_Id=D069_D006_Id
            LEFT JOIN D024 ON D024_Id=D070_D024_Id
            LEFT JOIN D020 ON D020_Id=D024_D020_Id
            LEFT JOIN D009 ON D009_Id=D069_D009_Id
            LEFT JOIN D049 ON D049_Id=D009_D049_Id
            LEFT JOIN D001 ON D001_Id=D049_D001_Id
         WHERE D069_Id=xD069_Id
         LIMIT 1;

        UPDATE D069 
        LEFT JOIN D009 ON D009_Id=D069_D009_Id
        LEFT JOIN D006 ON D006_Id=D069_D006_Id
                                set     D069_Valor_Preco_Unitario = D069_Valor_Preco_Original - (D069_Valor_Preco_Original * (ifnull(D069_Percentual_Desconto,0)/100)),
                                        D069_Valor_Preco_Sem_Desconto_Unitario = D069_Valor_Preco_Unitario,
                                        D069_Quantidade = 1,
                                        D069_Valor_Total_Preco = D069_Valor_Preco_Unitario*D069_Quantidade,
                                        D069_Valor_Total_Preco_Sem_Desconto = D069_Valor_Preco_Sem_Desconto_Unitario * D069_Quantidade,
                                        D069_Peso_Total = D069_Peso_Unitario*D069_Quantidade,
                                        D069_Peso_Bruto_Total = D069_Peso_Bruto*D069_Quantidade,
                                        D069_Valor_Total_Despesas=(D069_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,
                                        D069_Valor_Despesas_Unitario=D069_Valor_Total_Despesas/D069_Quantidade,
                                        D069_Valor_Total_Agregados=xValor_Total_Agregados,
                                        D069_Valor_Base_IPI=If(D069_Aliquota_IPI>0,(D069_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',D069_Valor_Total_Frete+D069_Valor_Total_Despesas_Acessorias,0))*If(D069_Percentual_Reducao_IPI>0,(D069_Percentual_Reducao_IPI/100),1),0),
                                        D069_Valor_IPI=D069_Valor_Base_IPI*(D069_Aliquota_IPI/100),
                                        D069_Valor_Total_Custo_Final=(D069_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',D069_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',D069_Valor_IPI,0)),
                                        D069_Valor_Custo_Final_Unitario=D069_Valor_Total_Custo_Final/D069_Quantidade,
                                        D069_Valor_Base_ICMS=If(D069_Aliquota_ICMS>0,D069_Valor_Total_Custo_Final*if(D069_Percentual_Reducao_ICMS>0,((100-D069_Percentual_Reducao_ICMS)/100),1),0),
                                        D069_Valor_ICMS=D069_Valor_Base_ICMS*(D069_Aliquota_ICMS/100),                                        
                                        D069_ST_VA_Ajustada = ( ( (1+(D069_ST_VA/100)) *   ( ( 1 - ( IF(D069_Percentual_Reducao_ICMS > 0, (((100-D069_Percentual_Reducao_ICMS)/100)*D069_ICMS_Inter_Estadual), D069_ICMS_Inter_Estadual) / 100 ) ) / ( 1 - ( D069_ST_ICMS_Interno / 100 ) ) ) ) - 1 ) * 100,
                                        D069_Valor_Base_ICMS_Substituicao=IF(D069_Flag_ST='S',(D069_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',D069_Valor_Total_Despesas,0)+D069_Valor_IPI)*((D069_ST_VA_Ajustada/100)+1),0),
                                        D069_Valor_ICMS_Substituicao=(D069_Valor_Base_ICMS_Substituicao*(D069_ST_ICMS_Interno/100)),
                                        D069_Valor_ICMS_Substituicao_Retencao=((D069_Valor_Base_ICMS_Substituicao*if(D069_Percentual_Reducao_ICMS_ST>0,((100-D069_Percentual_Reducao_ICMS_ST)/100),1))*(D069_ST_ICMS_Interno/100))-((D069_Valor_Total_Custo_Final*if(D069_Percentual_Reducao_ICMS>0,((100-D069_Percentual_Reducao_ICMS)/100),1))*(D069_ICMS_Inter_Estadual/100)),
                                        D069_Valor_ICMS_Substituicao_Retencao=IF(D069_ST_ICMS_Interno>0 and D069_ICMS_Inter_Estadual>0,IF(D069_Valor_ICMS_Substituicao_Retencao<0,0,D069_Valor_ICMS_Substituicao_Retencao),(D069_Valor_Total_Preco+D069_Valor_IPI)*(D069_Percentual_ST/100)),
                                        D069_Valor_Base_PIS=if(D069_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',D069_Valor_Total_Preco-D069_Valor_Total_Custo,D069_Valor_Total_Preco)),
                                        D069_Aliquota_PIS=if(D069_Flag_Isento_PIS='S',0,D069_Aliquota_PIS),
                                        D069_Valor_PIS=if(D069_Aliquota_PIS>0,D069_Valor_Base_PIS*(D069_Aliquota_PIS/100),0),
                                        D069_Valor_Base_COFINS=if(D069_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',D069_Valor_Total_Preco-D069_Valor_Total_Custo,D069_Valor_Total_Preco)),
                                        D069_Aliquota_COFINS=if(D069_Flag_Isento_COFINS='S',0,D069_Aliquota_COFINS),
                                        D069_Valor_COFINS=if(D069_Aliquota_COFINS>0,D069_Valor_Base_COFINS*(D069_Aliquota_COFINS/100),0),
                                        D069_Total_Cubagem = IFNULL(D069_Cubagem_Unitaria,0) * IFNULL(D069_Quantidade,0),
                                        D069_Valor_Trib_Transparencia=IFNULL(D069_Valor_Total_Preco,0)*(IFNULL(D069_Percentual_Trib_Transparencia,0)/100),
                                        D069_Valor_Frete=(D069_Valor_Total_Preco+D069_Valor_IPI+D069_Valor_ICMS_Substituicao_Retencao+D069_Valor_Financeiro) * (D069_Percentual_Frete/100),
                                        D069_Valor_Total_Custo=D069_Valor_Total_Preco+ifnull(D069_Valor_IPI,0)+ifnull(D069_Valor_ICMS_Substituicao_Retencao,0)+ifnull(D069_Valor_Frete,0)+ifnull(D069_Valor_Total_Frete,0)+ifnull(D069_Valor_Financeiro,0),
                                        D069_Valor_Custo_Unitario=D069_Valor_Total_Custo,
                                        D069_IPV=D009_IPV_1,
                                        D069_Percentual_ST=(D069_Valor_ICMS_Substituicao_Retencao/(D069_Valor_Total_Preco+D069_Valor_IPI))*100,
                                        D069_Valor_Preco_Venda=D069_Valor_Custo_Unitario*D069_IPV
                            WHERE D069_Id=xD069_Id;

END */$$
DELIMITER ;

/* Procedure structure for procedure `T002_Baixar_Titulo` */

/*!50003 DROP PROCEDURE IF EXISTS  `T002_Baixar_Titulo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T002_Baixar_Titulo`(xT002_Id int(11),xData date)
BEGIN
     DECLARE xT002_Valor_Saldo decimal(10,2);
     DECLARE xT002_Data_Recebimento date;
     UPDATE T002
        SET T002_Valor_Juros=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='C' group by T020_T002_Id),
            T002_Valor_Desconto=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='D' group by T020_T002_Id),
            T002_Valor_Recebido=(select sum(T019_Valor_Lancamento) from T019 where T019_T002_Id=T002_Id and T019_Flag_Excluido!='S'),
            T002_Valor_Total=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0),
            T002_Valor_Saldo=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)-ifnull(T002_Valor_Recebido,0)
      WHERE T002_Id=xT002_Id;
     SELECT T002_Valor_Saldo,
            T002_Data_Recebimento
       INTO xT002_Valor_Saldo,
            xT002_Data_Recebimento
       FROM T002
      WHERE T002_Id=xT002_Id;
     IF xT002_Valor_Saldo<=0 THEN
        IF xT002_Data_Recebimento='0000-00-00' THEN
           UPDATE T002
              SET T002_Data_Recebimento=xData,
                  T002_Data_Baixa=(select T019_Data_Lancamento from T019 where T019_T002_Id=T002_Id order by T019_Data_Lancamento desc limit 1)
            WHERE T002_Id=xT002_Id;
        END IF;
     ELSE
        UPDATE T002
           SET T002_Data_Recebimento='0000-00-00',
               T002_Data_Baixa='0000-00-00'
         WHERE T002_Id=xT002_Id;
     END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T002_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `T002_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T002_Gravar_Totalizacao`(xT002_Id int(11))
BEGIN
     UPDATE T002
        SET T002_Valor_Juros=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='C' group by T020_T002_Id),
            T002_Valor_Desconto=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='D' group by T020_T002_Id),
            T002_Valor_Taxas=(select sum(T020_Valor) from T020 where T020_T002_Id=T002_Id and T020_Flag_Deb_Cred='T' group by T020_T002_Id),
            T002_Valor_Recebido=(select sum(T019_Valor_Lancamento) from T019 where T019_T002_Id=T002_Id),
            T002_Valor_Total=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)-ifnull(T002_Valor_Taxas,0),
            T002_Valor_Saldo=ifnull(T002_Valor_Duplicata,0)+ifnull(T002_Valor_Juros,0)-ifnull(T002_Valor_Desconto,0)-ifnull(T002_Valor_Taxas,0)-ifnull(T002_Valor_Recebido,0),
            T002_Valor_Total_Cheques=(select sum(T246_Valor) from T246 Where T246_T002_Id=T002_Id)
      WHERE T002_Id=xT002_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T003_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `T003_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` PROCEDURE `T003_Gravar_Totalizacao`(xT003_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    SELECT sum(T004_Valor_Total_Custo),
           sum(T004_Valor_Total_Custo_Confirmado),
           sum(T004_Valor_Total_Preco),
           sum(T004_Valor_Total_Preco_Confirmado),
           sum(T004_Valor_Total_Preco_Sem_Desconto),
           sum(T004_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T004_Valor_Total_Custo_Final),
           sum(T004_Valor_Total_Custo_Final_Confirmado),
           sum(T004_Valor_ICMS),
           sum(T004_Valor_ICMS_Confirmado),
           sum(T004_Valor_Base_ICMS),
           sum(T004_Valor_Base_ICMS_Confirmado),
           sum(T004_Valor_IPI),
           sum(T004_Valor_IPI_Confirmado),
           sum(T004_Valor_Base_IPI),
           sum(T004_Valor_Base_IPI_Confirmado),
           sum(T004_Peso_Total),
           sum(T004_Peso_Total_Confirmado),
           sum(T004_Valor_Total_Desconto),
           sum(T004_Valor_Total_Desconto_Confirmado),
           sum(T004_Valor_Base_ST),
           sum(T004_Valor_ST),
           sum(T004_Valor_Base_ST_Confirmado),
           sum(T004_Valor_ST_Confirmado)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado
           FROM T004
           WHERE T004_T003_Id=xT003_Id
             AND T004_Flag_Cancelado!='S';
    UPDATE T003 SET T003_Valor_Total_Produtos=xValor_Total_Preco,
                    T003_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T003_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T003_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T003_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T003_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T003_Valor_Total_Custo=xValor_Total_Custo,
                    T003_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T003_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T003_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T003_Valor_Total_ICMS=xValor_ICMS,
                    T003_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T003_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T003_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T003_Valor_Total_IPI=xValor_IPI,
                    T003_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T003_Valor_ISS=if(T003_Aliquota_ISS>0,T003_Valor_Mao_Obra*(T003_Aliquota_ISS/100),0),
                    T003_Valor_Base_ST=xValor_Base_ST,
                    T003_Valor_ST=xValor_ST,
                    T003_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T003_Valor_Desconto=xValor_Total_Desconto,
                    T003_Valor_Desconto_Confirmado=xValor_Total_Desconto_Confirmado,
                    T003_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T003_Valor_Total=T003_Valor_Total_Produtos+
                                     T003_Valor_Mao_Obra+
                                     T003_Valor_Despesas_Acessorias+
                                     T003_Valor_Total_IPI+
                                     T003_Valor_ST+
                                     if (T003_Flag_Frete=1,T003_Valor_Frete,0),
                    T003_Valor_Total_Confirmado=if(T003_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     T003_Valor_Total_Produtos_Confirmado+
                                     T003_Valor_Mao_Obra+
                                     T003_Valor_Despesas_Acessorias+
                                     T003_Valor_Total_IPI_Confirmado+
                                     T003_Valor_ST_Confirmado+
                                     if (T003_Flag_Frete=1,T003_Valor_Frete,0),0),
                    T003_Valor_Total_Abertos=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado!='S' AND T004_Id NOT IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)),
                    T003_Valor_Total_Fechados=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado!='S' AND T004_Id IN (SELECT T004_Id FROM T006 LEFT JOIN T004 ON T004_Id=T006_T004_Id WHERE T004_T003_Id=xT003_Id)),
                    T003_Valor_Total_Cancelados=(SELECT SUM(T004_Valor_Total_Preco) from T004 WHERE T004_T003_Id=xT003_Id AND T004_Flag_Cancelado='S'),
                    T003_IPV=T003_IPV_Medio(xT003_Id,1),
                    T003_IPV_Confirmado=T003_IPV_Medio(xT003_Id,2),
                    T003_IPV_Normal=T003_IPV_Medio(xT003_Id,3),
                    T003_IPV_Normal_Confirmado=T003_IPV_Medio(xT003_Id,4),
                    T003_Peso_Total=xPeso_Total,
                    T003_Peso_Total_Confirmado=xPeso_Total_Confirmado
              WHERE T003_Id=xT003_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T003_Gravar_Totalizacao_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `T003_Gravar_Totalizacao_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T003_Gravar_Totalizacao_3`(xT003_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_PIS DECIMAL(10,2);
    DECLARE xValor_COFINS DECIMAL(10,2);
    DECLARE xValor_ICMS_Desonerado DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    DECLARE xValorPendente DECIMAL(14,5) DEFAULT 0;
    DECLARE xC004_Id int(10);
    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);
    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);
    DECLARE xC031_Desabilitar_Cotacao_Emergencia varchar(1);
    DECLARE xC031_Exibir_Msg_Cotar_Orcamento varchar(1);
    DECLARE xFlagItensPendenteOrcamento int(10);
    DECLARE xValor_IRPJ DECIMAL(10,2);
    DECLARE xValor_Base_IRPJ DECIMAL(10,2);
    DECLARE xValor_CSLL DECIMAL(10,2);
    DECLARE xValor_Base_CSLL DECIMAL(10,2);

    SELECT sum(T004_Valor_Total_Custo),
           sum(T004_Valor_Total_Custo_Confirmado),
           sum(T004_Valor_Total_Preco),
           sum(T004_Valor_Total_Preco_Confirmado),
           sum(T004_Valor_Total_Preco_Sem_Desconto),
           sum(T004_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T004_Valor_Total_Custo_Final),
           sum(T004_Valor_Total_Custo_Final_Confirmado),
           sum(T004_Valor_ICMS),
           sum(T004_Valor_ICMS_Confirmado),
           sum(T004_Valor_ICMS_Desonerado),
           sum(T004_Valor_Total_Agregados),
           sum(T004_Valor_Base_ICMS),
           sum(T004_Valor_Base_ICMS_Confirmado),
           sum(T004_Valor_IPI),
           sum(T004_Valor_IPI_Confirmado),
           sum(T004_Valor_Base_IPI),
           sum(T004_Valor_Base_IPI_Confirmado),
           sum(T004_Peso_Total),
           sum(T004_Peso_Bruto_Total),
           sum(T004_Peso_Total_Confirmado),
           sum(T004_Valor_Total_Desconto),
           sum(T004_Valor_Total_Desconto_Confirmado),
           sum(T004_Valor_Base_ST),
           sum(T004_Valor_ST),
           sum(T004_Valor_Base_ST_Confirmado),
           sum(T004_Valor_ST_Confirmado),
           sum(T004_Valor_Preco_Bruto),
           sum(T004_Total_Cubagem),
           sum(T004_Valor_Trib_Transparencia),
           sum(T004_Valor_PIS),
           sum(T004_Valor_COFINS),
           sum(T004_Valor_IRPJ),
           sum(T004_Valor_Base_IRPJ),
           sum(T004_Valor_CSLL),
           sum(T004_Valor_Base_CSLL)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_ICMS_Desonerado,
           xValor_Total_Agregados,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Bruto_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia,
           xValor_PIS,
           xValor_COFINS,
           xValor_IRPJ,
           xValor_Base_IRPJ,
           xValor_CSLL,
           xValor_Base_CSLL
           FROM T004
           LEFT JOIN T003 ON T003_Id=T004_T003_Id   
           WHERE T004_T003_Id=xT003_Id
             AND (T004_Flag_Cancelado!='S' OR T003_Flag_Perdido='S');
    
    SELECT SUM(T145_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T145
     WHERE T145_T003_Id=xT003_Id;

    SELECT T003_C004_Id
      INTO xC004_Id     
      FROM T003
     WHERE T003_Id=xT003_Id;
    
    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T003_Id=xT003_Id;
    
    SELECT SUM(distinct if(T004_Valor_Total_Preco>ifnull(T006_Valor_Total_Preco,0),T004_Valor_Total_Preco-ifnull(T006_Valor_Total_Preco,0),0))
      INTO xValorPendente
      FROM T004
      LEFT JOIN T006 ON T006_T004_Id=T004_Id
      WHERE T004_T003_Id=xT003_Id;

    SET xFlagItensPendenteOrcamento = 0;

    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Desabilitar_Cotacao_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCotacaoEmergencia' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Exibir_Msg_Cotar_Orcamento FROM C031 WHERE C031_Campo = 'exibirMsgCotarOrcamento' AND C031_C004_Id = xC004_Id;

    SELECT IFNULL(COUNT(T004_Id),0)
      INTO xFlagItensPendenteOrcamento
      FROM T004
 LEFT JOIN D009 ON D009_Id=T004_D009_Id
 LEFT JOIN D049 ON D049_Id=D009_D049_Id
 LEFT JOIN D069 ON D069_Id=D009_D069_Id
 LEFT JOIN D070 ON D070_Id=D069_D070_Id
     WHERE (D009_Quantidade_Estoque+D009_Quantidade_OC) < T004_Quantidade 
       AND IFNULL(T004_T219_Id,0) <= 0 
       AND IFNULL(D049_Flag_Tipo,'') = 'CP' 
       AND T004_T003_Id=xT003_Id
       AND xC031_Exibir_Msg_Cotar_Orcamento = 'S'
       AND (D009_Valor_Custo_Tabela <= 0 OR D070_Data_Vencimento < CURRENT_DATE());

    UPDATE T003 SET T003_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T003_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T003_Valor_Total_Produtos=xValor_Total_Preco,
                    T003_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T003_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T003_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T003_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T003_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T003_Valor_Total_Custo=xValor_Total_Custo,
                    T003_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T003_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T003_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T003_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T003_Valor_Total_ICMS=xValor_ICMS,
                    T003_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T003_Valor_Total_ICMS_Desonerado=xValor_ICMS_Desonerado,
                    T003_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T003_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T003_Valor_Total_IPI=xValor_IPI,
                    T003_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T003_Valor_ISS=if(T003_Aliquota_ISS>0,T003_Valor_Mao_Obra*(T003_Aliquota_ISS/100),0),
                    T003_Valor_Base_ST=xValor_Base_ST,
                    T003_Valor_ST=xValor_ST,
                    T003_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T003_Valor_Desconto=IF(xC031_Desabilitar_Cotacao_Emergencia='S' OR xFlagItensPendenteOrcamento = 0,(T003_Valor_Total_Produtos_Sem_Desconto-T003_Valor_Total_Produtos),0),
                    T003_Valor_Desconto_Confirmado=IF(xC031_Desabilitar_Cotacao_Emergencia='S' OR xFlagItensPendenteOrcamento = 0,(T003_Valor_Total_Produtos_Sem_Desconto_Confirmado-T003_Valor_Total_Produtos_Confirmado),0),                   
                    T003_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T003_Valor_Total_Base_IRPJ=xValor_Base_IRPJ,
                    T003_Valor_Total_IRPJ=xValor_IRPJ,
                    T003_Valor_Total_Base_CSLL=xValor_Base_CSLL,
                    T003_Valor_Total_CSLL=xValor_CSLL,
                    T003_Valor_Total_PIS=xValor_PIS,
                    T003_Valor_Total_COFINS=xValor_COFINS,
                    T003_Valor_Total=ifnull(T003_Valor_Total_Produtos,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T003_Valor_Total_Agregados),0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI,0)+
                                     ifnull(T003_Valor_ST,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),
                    T003_Valor_Total_Confirmado=if(T003_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     ifnull(T003_Valor_Total_Produtos_Confirmado,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI_Confirmado,0)+
                                     ifnull(T003_Valor_ST_Confirmado,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual_Confirmado,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),0),
                    T003_IPV=if(T003_Valor_Total_Custo>0,(T003_Valor_Total_Produtos-
                                     IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                     IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                     IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                     IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                     IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))/T003_Valor_Total_Custo,0),
                    T003_Percentual_Margem=round((((T003_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))-T003_Valor_Total_Custo)/
                                          (T003_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0)))*100,2),
                    T003_IPV_Confirmado=if(T003_Valor_Total_Custo_Confirmado>0,T003_Valor_Total_Produtos_Confirmado/T003_Valor_Total_Custo_Confirmado,0),
                    T003_IPV_Normal=ifnull(T003_IPV_Medio(xT003_Id,3),0),
                    T003_IPV_Normal_Confirmado=T003_IPV_Medio(xT003_Id,4),
                    T003_Peso_Total=ifnull(xPeso_Total,0),
                    T003_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T003_Peso_Total_Confirmado=ifnull(xPeso_Total_Confirmado,0),
                    T003_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T003_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,
                    T003_Valor_Pendente=xValorPendente                    
              WHERE T003_Id=xT003_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T003_Gravar_Totalizacao_4` */

/*!50003 DROP PROCEDURE IF EXISTS  `T003_Gravar_Totalizacao_4` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T003_Gravar_Totalizacao_4`(xT003_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Produtos DECIMAL(10,2);
    DECLARE xValor_Total_Produtos_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_PIS DECIMAL(10,2);
    DECLARE xValor_COFINS DECIMAL(10,2);
    DECLARE xValor_ICMS_Desonerado DECIMAL(10,2);
    DECLARE xValor_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Confirmado DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_IPI_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI_Confirmado DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xIPV_Confirmado DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xPeso_Total_Confirmado DECIMAL(10,3);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Desconto_Confirmado DECIMAL(10,2);
    DECLARE xValor_Base_ST DECIMAL(10,2);
    DECLARE xValor_ST DECIMAL(10,2);
    DECLARE xValor_Base_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_ST_Confirmado DECIMAL(10,2);
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    DECLARE xValorPendente DECIMAL(14,5) DEFAULT 0;
    DECLARE xC004_Id int(10);
    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);
    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);
    DECLARE xC031_Desabilitar_Cotacao_Emergencia varchar(1);
    DECLARE xC031_Exibir_Msg_Cotar_Orcamento varchar(1);
    DECLARE xFlagItensPendenteOrcamento int(10);
    DECLARE xValor_IRPJ DECIMAL(10,2);
    DECLARE xValor_Base_IRPJ DECIMAL(10,2);
    DECLARE xValor_CSLL DECIMAL(10,2);
    DECLARE xValor_Base_CSLL DECIMAL(10,2);

    SELECT sum(T004_Valor_Total_Custo),
           sum(T004_Valor_Total_Custo_Confirmado),
           sum(T004_Valor_Total_Preco),
           sum(T004_Valor_Total_Preco_Confirmado),
           sum(T004_Valor_Total_Preco_Sem_Desconto),
           sum(T004_Valor_Total_Preco_Sem_Desconto_Confirmado),
           sum(T004_Valor_Total_Custo_Final),
           sum(T004_Valor_Total_Custo_Final_Confirmado),
           sum(T004_Valor_ICMS),
           sum(T004_Valor_ICMS_Confirmado),
           sum(T004_Valor_ICMS_Desonerado),
           sum(T004_Valor_Total_Agregados),
           sum(T004_Valor_Base_ICMS),
           sum(T004_Valor_Base_ICMS_Confirmado),
           sum(T004_Valor_IPI),
           sum(T004_Valor_IPI_Confirmado),
           sum(T004_Valor_Base_IPI),
           sum(T004_Valor_Base_IPI_Confirmado),
           sum(T004_Peso_Total),
           sum(T004_Peso_Bruto_Total),
           sum(T004_Peso_Total_Confirmado),
           sum(T004_Valor_Total_Desconto),
           sum(T004_Valor_Total_Desconto_Confirmado),
           sum(T004_Valor_Base_ST),
           sum(T004_Valor_ST),
           sum(T004_Valor_Base_ST_Confirmado),
           sum(T004_Valor_ST_Confirmado),
           sum(T004_Valor_Preco_Bruto),
           sum(T004_Total_Cubagem),
           sum(T004_Valor_Trib_Transparencia),
           sum(T004_Valor_PIS),
           sum(T004_Valor_COFINS),
           sum(T004_Valor_IRPJ),
           sum(T004_Valor_Base_IRPJ),
           sum(T004_Valor_CSLL),
           sum(T004_Valor_Base_CSLL)
      INTO xValor_Total_Custo,
           xValor_Total_Custo_Confirmado,
           xValor_Total_Preco,
           xValor_Total_Preco_Confirmado,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Preco_Sem_Desconto_Confirmado,
           xValor_Total_Custo_Final,
           xValor_Total_Custo_Final_Confirmado,
           xValor_ICMS,
           xValor_ICMS_Confirmado,
           xValor_ICMS_Desonerado,
           xValor_Total_Agregados,
           xValor_Base_ICMS,
           xValor_Base_ICMS_Confirmado,
           xValor_IPI,
           xValor_IPI_Confirmado,
           xValor_Base_IPI,
           xValor_Base_IPI_Confirmado,
           xPeso_Total,
           xPeso_Bruto_Total,
           xPeso_Total_Confirmado,
           xValor_Total_Desconto,
           xValor_Total_Desconto_Confirmado,
           xValor_Base_ST,
           xValor_ST,
           xValor_Base_ST_Confirmado,
           xValor_ST_Confirmado,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia,
           xValor_PIS,
           xValor_COFINS,
           xValor_IRPJ,
           xValor_Base_IRPJ,
           xValor_CSLL,
           xValor_Base_CSLL
           FROM T004
           LEFT JOIN T003 ON T003_Id=T004_T003_Id   
           WHERE T004_T003_Id=xT003_Id
             AND (T004_Flag_Cancelado!='S' OR T003_Flag_Perdido='S');
    
    SELECT SUM(T145_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T145
     WHERE T145_T003_Id=xT003_Id;

    SELECT T003_C004_Id
      INTO xC004_Id     
      FROM T003
     WHERE T003_Id=xT003_Id;
    
    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T003_Id=xT003_Id;
    
    SELECT SUM(distinct if(T004_Valor_Total_Preco>ifnull(T006_Valor_Total_Preco,0),T004_Valor_Total_Preco-ifnull(T006_Valor_Total_Preco,0),0))
      INTO xValorPendente
      FROM T004
      LEFT JOIN T006 ON T006_T004_Id=T004_Id
      WHERE T004_T003_Id=xT003_Id;

    SET xFlagItensPendenteOrcamento = 0;

    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Desabilitar_Cotacao_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCotacaoEmergencia' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Exibir_Msg_Cotar_Orcamento FROM C031 WHERE C031_Campo = 'exibirMsgCotarOrcamento' AND C031_C004_Id = xC004_Id;

    SELECT IFNULL(COUNT(T004_Id),0)
      INTO xFlagItensPendenteOrcamento
      FROM T004
 LEFT JOIN D009 ON D009_Id=T004_D009_Id
 LEFT JOIN D049 ON D049_Id=D009_D049_Id
 LEFT JOIN D069 ON D069_Id=D009_D069_Id
 LEFT JOIN D070 ON D070_Id=D069_D070_Id
     WHERE (D009_Quantidade_Estoque+D009_Quantidade_OC) < T004_Quantidade 
       AND IFNULL(T004_T219_Id,0) <= 0 
       AND IFNULL(D049_Flag_Tipo,'') = 'CP' 
       AND T004_T003_Id=xT003_Id
       AND xC031_Exibir_Msg_Cotar_Orcamento = 'S'
       AND (D009_Valor_Custo_Tabela <= 0 OR D070_Data_Vencimento < CURRENT_DATE());

    UPDATE T003 SET T003_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T003_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T003_Valor_Total_Produtos=xValor_Total_Preco,
                    T003_Valor_Total_Produtos_Confirmado=xValor_Total_Preco_Confirmado,
                    T003_Valor_Total_Produtos_Sem_Desconto=xValor_Total_Preco_Sem_Desconto,
                    T003_Valor_Total_Produtos_Sem_Desconto_Confirmado=xValor_Total_Preco_Sem_Desconto_Confirmado,
                    T003_Valor_Total_Custo_Final=xValor_Total_Custo_Final,
                    T003_Valor_Total_Custo_Final_Confirmado=xValor_Total_Custo_Final_Confirmado,
                    T003_Valor_Total_Custo=xValor_Total_Custo,
                    T003_Valor_Total_Custo_Confirmado=xValor_Total_Custo_Confirmado,
                    T003_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T003_Valor_Total_Base_ICMS=xValor_Base_ICMS,
                    T003_Valor_Total_Base_ICMS_Confirmado=xValor_Base_ICMS_Confirmado,
                    T003_Valor_Total_ICMS=xValor_ICMS,
                    T003_Valor_Total_ICMS_Confirmado=xValor_ICMS_Confirmado,
                    T003_Valor_Total_ICMS_Desonerado=xValor_ICMS_Desonerado,
                    T003_Valor_Total_Base_IPI=xValor_Base_IPI,
                    T003_Valor_Total_Base_IPI_Confirmado=xValor_Base_IPI_Confirmado,
                    T003_Valor_Total_IPI=xValor_IPI,
                    T003_Valor_Total_IPI_Confirmado=xValor_IPI_Confirmado,
                    T003_Valor_ISS=if(T003_Aliquota_ISS>0,T003_Valor_Mao_Obra*(T003_Aliquota_ISS/100),0),
                    T003_Valor_Base_ST=xValor_Base_ST,
                    T003_Valor_ST=xValor_ST,
                    T003_Valor_Base_ST_Confirmado=xValor_Base_ST_Confirmado,
                    T003_Valor_Desconto=IF(xC031_Desabilitar_Cotacao_Emergencia='S' OR xFlagItensPendenteOrcamento = 0,(T003_Valor_Total_Produtos_Sem_Desconto-T003_Valor_Total_Produtos),0),
                    T003_Valor_Desconto_Confirmado=IF(xC031_Desabilitar_Cotacao_Emergencia='S' OR xFlagItensPendenteOrcamento = 0,(T003_Valor_Total_Produtos_Sem_Desconto_Confirmado-T003_Valor_Total_Produtos_Confirmado),0),                   
                    T003_Valor_ST_Confirmado=xValor_ST_Confirmado,
                    T003_Valor_Total_Base_IRPJ=xValor_Base_IRPJ,
                    T003_Valor_Total_IRPJ=xValor_IRPJ,
                    T003_Valor_Total_Base_CSLL=xValor_Base_CSLL,
                    T003_Valor_Total_CSLL=xValor_CSLL,
                    T003_Valor_Total_PIS=xValor_PIS,
                    T003_Valor_Total_COFINS=xValor_COFINS,
                    T003_Valor_Total=ifnull(T003_Valor_Total_Produtos,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T003_Valor_Total_Agregados),0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI,0)+
                                     ifnull(T003_Valor_ST,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),
                    T003_Valor_Total_Confirmado=if(T003_Flag_Confirmar_Mao_Obra='S' or ifnull(xValor_Total_Preco_Confirmado,0)>0,
                                     ifnull(T003_Valor_Total_Produtos_Confirmado,0)+
                                     ifnull(T003_Valor_Mao_Obra,0)+
                                     ifnull(T003_Valor_Despesas_Acessorias,0)+
                                     ifnull(T003_Valor_Total_IPI_Confirmado,0)+
                                     ifnull(T003_Valor_ST_Confirmado,0)+
                                     ifnull(T003_Valor_Total_Servicos,0)-
                                     ifnull(T003_Valor_Desconto_Manual_Confirmado,0)-
                                     ifnull(T003_Valor_Troca,0)+
                                     ifnull(T003_Valor_Frete,0),0),
                    T003_IPV=if(T003_Valor_Total_Custo>0,(T003_Valor_Total_Produtos-
                                     IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                     IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                     IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                     IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                     IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))/T003_Valor_Total_Custo,0),
                    T003_Percentual_Margem=round((((T003_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))-T003_Valor_Total_Custo)/
                                          (T003_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T003_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0)))*100,2),
                    T003_IPV_Confirmado=if(T003_Valor_Total_Custo_Confirmado>0,T003_Valor_Total_Produtos_Confirmado/T003_Valor_Total_Custo_Confirmado,0),
                    T003_IPV_Normal=ifnull(T003_IPV_Medio(xT003_Id,3),0),
                    T003_IPV_Normal_Confirmado=T003_IPV_Medio(xT003_Id,4),
                    T003_Peso_Total=ifnull(xPeso_Total,0),
                    T003_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T003_Peso_Total_Confirmado=ifnull(xPeso_Total_Confirmado,0),
                    T003_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T003_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,
                    T003_Valor_Pendente=xValorPendente                    
              WHERE T003_Id=xT003_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T004_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `T004_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T004_Gravar_Totalizacao`(xT004_Id int(11))
BEGIN

    DECLARE xT003_Id INT;

    DECLARE xPercentual_Desconto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Confirmado DECIMAL(30,20) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesa_Confirmado DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS varchar(1);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xTotal_Itens INT(5);

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xFlag_ACP VARCHAR(1);

    DECLARE xT003_Casas_Decimais_Preco int(2);

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Cotacao_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);



      SELECT T004_T003_Id,

           T003_Flag_ACP,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_ST,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto_Bruto/100,

           T004_C004_Id,

           T003_Casas_Decimais_Preco,

           D006_Flag_Isento_ICMS

      INTO xT003_Id,

           xFLag_ACP,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_ST,

           xPercentual_Desconto,

           xPercentual_Desconto_Confirmado,

           xPercentual_Desconto_Bruto,

           xC004_Id,

           xT003_Casas_Decimais_Preco,

           xD006_Flag_Isento_ICMS

      FROM T004

      LEFT JOIN D006 ON D006_Id=T004_D006_Id

      LEFT JOIN T003 ON T003_Id=T004_T003_Id

      WHERE T004_Id=xT004_Id;



      SELECT C004_Casas_Decimais_Preco,

           C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

           xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



      SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Desabilitar_Cotacao_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCotacaoEmergencia' AND C031_C004_Id = xC004_Id;



      if !(xPercentual_Desconto>0 OR xPercentual_Desconto<0) THEN

         SELECT T003_Percentual_Desconto/100,

                T003_Percentual_Desconto_Confirmado/100

           INTO xPercentual_Desconto,

                xPercentual_Desconto_Confirmado

         FROM T003

         LEFT JOIN C004 ON C004_Id=T003_C004_Id

         WHERE T003_Id=xT003_Id;

      END IF;



      SELECT SUM(T202_Valor_Unitario) INTO xValor_Total_Agregados FROM T202 WHERE T202_T004_Id=xT004_Id;



      IF xPercentual_Desconto IS NULL THEN

         set xPercentual_Desconto = 0;

      END IF;

      IF xPercentual_Desconto_Bruto IS NULL THEN

         set xPercentual_Desconto_Bruto = 0;

      END IF;

       IF xPercentual_Desconto_Confirmado IS NULL THEN

         set xPercentual_Desconto_Confirmado = 0;

      END IF;



      UPDATE T004

      LEFT JOIN D009 ON D009_Id=T004_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

         SET T004_Valor_Desconto_Unitario = if((xPercentual_Desconto>0 or xPercentual_Desconto<0) and T004_Valor_Preco_Original>0,T004_Valor_Preco_Original*xPercentual_Desconto,0),

             T004_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T004_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

             T004_Valor_Desconto_Unitario_Confirmado = if(xPercentual_Desconto_Confirmado>0 or xPercentual_Desconto_Confirmado<0,T004_Valor_Preco_Original*xPercentual_Desconto_Confirmado,0),

             T004_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0, T004_Valor_Desconto_Unitario*T004_Quantidade, 0),

             T004_Valor_Total_Desconto_Confirmado=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0, T004_Valor_Desconto_Unitario_Confirmado*T004_Quantidade, 0),

             T004_Valor_Preco_Unitario = if(T004_Valor_Preco_Original>0,round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario,xT003_Casas_Decimais_Preco),T004_Valor_Preco_Unitario),

             T004_Valor_Preco_Bruto = round(T004_Valor_Preco_Original_Bruto - T004_Valor_Desconto_Unitario_Bruto,xT003_Casas_Decimais_Preco),

             T004_Valor_Preco_Unitario_Confirmado = round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario_Confirmado,xT003_Casas_Decimais_Preco),

             T004_Valor_Total_Preco = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario*T004_Quantidade,2),T004_Valor_Preco_Unitario*T004_Quantidade),

             T004_Valor_Total_Preco_Confirmado = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada,2), T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada),

             T004_Valor_Total_Preco_Sem_Desconto =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade,2),T004_Valor_Preco_Original * T004_Quantidade),

             T004_Valor_Total_Preco_Sem_Desconto_Confirmado =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade_Confirmada,2), T004_Valor_Preco_Original * T004_Quantidade_Confirmada),

             T004_Valor_Total_Agregados=xValor_Total_Agregados,

             T004_Aliquota_PIS=if(T004_Flag_Isento_PIS='S',0,T004_Aliquota_PIS),

             T004_Aliquota_COFINS=if(T004_Flag_Isento_COFINS='S',0,T004_Aliquota_COFINS),

             T004_Valor_Base_PIS=if(T004_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_PIS=if(T004_Aliquota_PIS>0,T004_Valor_Base_PIS*(T004_Aliquota_PIS/100),0),

             T004_Valor_Base_COFINS=if(T004_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_COFINS=if(T004_Aliquota_COFINS>0,T004_Valor_Base_COFINS*(T004_Aliquota_COFINS/100),0),

             T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;



       SELECT (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade),

                 (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade_Confirmada),

                 T003_Flag_Revenda_Consumidor

        INTO xMultiplicador_Despesa,

              xMultiplicador_Despesa_Confirmado,

              xFlag_Revenda_Consumidor

        FROM T003

        LEFT JOIN T004 ON T004_T003_Id=T003_Id

       WHERE T003_Id=xT003_Id

       GROUP BY T003_Id;

       IF xMultiplicador_Despesa IS NULL THEN

           set xMultiplicador_Despesa = 0;

       END IF;

       IF xMultiplicador_Despesa_Confirmado IS NULL THEN

           set xMultiplicador_Despesa_Confirmado = 0;

       END IF;

       

        SELECT COUNT(*) INTO xTotal_Itens FROM T004 WHERE T004_T003_Id = xT003_Id;



    SELECT T003_Valor_Frete/SUM(T004_Valor_Preco_Unitario*T004_Quantidade),

        T003_Valor_Frete,

        T003_Valor_Despesas_Acessorias/SUM(T004_Valor_Preco_Unitario*T004_Quantidade)

    INTO xMultiplicador_Frete,

      xValor_Total_Frete,

      xMultiplicador_Despesas_Acessorias

    FROM T003

    LEFT JOIN T004 ON T004_T003_Id=T003_Id

    WHERE T003_Id=xT003_Id

    GROUP BY T003_Id;



    UPDATE T004 SET T004_Valor_Total_Despesas_Acessorias=T004_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

        T004_Valor_Despesas_Acessorias_Unitario=T004_Valor_Total_Despesas_Acessorias/T004_Quantidade,

        T004_Valor_Frete_Total=IF(xC004_Flag_Rateio_Frete=1,T004_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

        T004_Valor_Frete_Unitario=T004_Valor_Frete_Total/T004_Quantidade

    WHERE T004_Id=xT004_Id;

       

    UPDATE T004

    SET T004_Valor_Total_Custo=T004_Valor_Custo_Unitario*T004_Quantidade,

                    T004_Valor_Total_Custo_Confirmado=T004_Valor_Custo_Unitario*T004_Quantidade_Confirmada,

                    T004_Peso_Total=T004_Peso_Unitario*T004_Quantidade,

                    T004_Peso_Bruto_Total=T004_Peso_Bruto*T004_Quantidade,

                    T004_Peso_Total_Confirmado=T004_Peso_Unitario*T004_Quantidade_Confirmada,

                    T004_Valor_Total_Despesas=(T004_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T004_Valor_Total_Despesas_Confirmado=T004_Valor_Total_Preco_Confirmado*xMultiplicador_Despesa_Confirmado,

                    T004_Valor_Despesas_Unitario=T004_Valor_Total_Despesas/T004_Quantidade,

                    T004_Valor_Despesas_Unitario_Confirmado=T004_Valor_Total_Despesas_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_IPI=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco)*IF(T004_Percentual_Reducao_IPI>0,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_Base_IPI_Confirmado=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco_Confirmado)*IF(T004_Percentual_Reducao_IPI,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_IPI=T004_Valor_Base_IPI*(T004_Aliquota_IPI/100),

                    T004_Valor_IPI_Confirmado=T004_Valor_Base_IPI_Confirmado*(T004_Aliquota_IPI/100),

                    T004_Valor_Total_Custo_Final=(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Total_Custo_Final_Confirmado=(T004_Valor_Total_Preco_Confirmado+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas_Confirmado,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Custo_Final_Unitario=T004_Valor_Total_Custo_Final/T004_Quantidade,

                    T004_Valor_Custo_Final_Unitario_Confirmado=T004_Valor_Total_Custo_Final_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_ICMS=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Confirmado=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Desonerado=IF(T004_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T004_Valor_Total_Custo_Final-IF(T004_Percentual_Reducao_ICMS>0,T004_Valor_Base_ICMS,0),0),

                    T004_Valor_ICMS=T004_Valor_Base_ICMS*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Confirmado=T004_Valor_Base_ICMS_Confirmado*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Desonerado=T004_Valor_Base_ICMS_Desonerado*(T004_Aliquota_ICMS_Oculto/100),

                    T004_Valor_Base_ST=IF(T004_Flag_ST='S',(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+T004_Valor_IPI)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST=IF(T004_Flag_ST='S',((T004_Valor_Base_ST*IF(T004_Percentual_Reducao_ICMS_ST>0,((100-T004_Percentual_Reducao_ICMS_ST)/100),1))*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST=IF(T004_Valor_ST<0,0,T004_Valor_ST),

                    T004_Valor_Base_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Total_Custo_Final_Confirmado+T004_Valor_Despesas_Unitario_Confirmado+T004_Valor_IPI_Confirmado)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Base_ST_Confirmado*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST_Confirmado=IF(T004_Valor_ST_Confirmado<0,0,T004_Valor_ST_Confirmado),

                    T004_IPV=(T004_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0))/T004_Valor_Custo_Unitario,

                    T004_Percentual_Margem=round((((T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0))-T004_Valor_Custo_Unitario)/

                              (T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)))*100,2),

                    T004_Valor_Lucro=round((T004_Valor_Total_Custo*T004_IPV)-(T004_Valor_Total_Custo*T004_IPV_Sem_Lucro),2),

                    T004_Total_Cubagem = IFNULL(T004_Cubagem_Unitaria, 0) * IFNULL(T004_Quantidade,0),

                    T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;

       CALL T003_Gravar_Totalizacao(xT003_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T004_Gravar_Totalizacao_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `T004_Gravar_Totalizacao_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T004_Gravar_Totalizacao_3`(xT004_Id int(11))
BEGIN

    DECLARE xT003_Id INT;

    DECLARE xPercentual_Desconto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Confirmado DECIMAL(30,20) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesa_Confirmado DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS varchar(1);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xTotal_Itens INT(5);

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xFlag_ACP VARCHAR(1);

    DECLARE xT003_Casas_Decimais_Preco int(2);

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);

    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Cotacao_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);

    DECLARE xD070_Data_Vencimento date;



      SELECT T004_T003_Id,

           T003_Flag_ACP,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_ST,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto_Bruto/100,

           T004_C004_Id,

           T003_Casas_Decimais_Preco,

           D006_Flag_Isento_ICMS

      INTO xT003_Id,

           xFLag_ACP,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_ST,

           xPercentual_Desconto,

           xPercentual_Desconto_Confirmado,

           xPercentual_Desconto_Bruto,

           xC004_Id,

           xT003_Casas_Decimais_Preco,

           xD006_Flag_Isento_ICMS

      FROM T004

      LEFT JOIN D006 ON D006_Id=T004_D006_Id

      LEFT JOIN T003 ON T003_Id=T004_T003_Id

      WHERE T004_Id=xT004_Id;



      SELECT C004_Casas_Decimais_Preco,

           C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

           xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



      SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Desabilitar_Cotacao_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCotacaoEmergencia' AND C031_C004_Id = xC004_Id;



      if !(xPercentual_Desconto>0 OR xPercentual_Desconto<0) THEN

         SELECT T003_Percentual_Desconto/100,

                T003_Percentual_Desconto_Confirmado/100

           INTO xPercentual_Desconto,

                xPercentual_Desconto_Confirmado

         FROM T003

         LEFT JOIN C004 ON C004_Id=T003_C004_Id

         WHERE T003_Id=xT003_Id;

      END IF;



      SELECT SUM(T202_Valor_Unitario) INTO xValor_Total_Agregados FROM T202 WHERE T202_T004_Id=xT004_Id;



      IF xPercentual_Desconto IS NULL THEN

         set xPercentual_Desconto = 0;

      END IF;

      IF xPercentual_Desconto_Bruto IS NULL THEN

         set xPercentual_Desconto_Bruto = 0;

      END IF;

       IF xPercentual_Desconto_Confirmado IS NULL THEN

         set xPercentual_Desconto_Confirmado = 0;

      END IF;



      SELECT IFNULL(D070_Data_Vencimento,'0000-00-00')

        INTO xD070_Data_Vencimento

      FROM D070

      LEFT JOIN D069 ON D070_Id=D069_D070_Id

      LEFT JOIN D009 ON D009_Id=D009_D069_Id

      LEFT JOIN T004 ON D009_Id=T004_D009_Id

      WHERE T004_Id=xT004_Id;



      UPDATE T004

      LEFT JOIN D009 ON D009_Id=T004_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id      

         SET T004_Valor_Desconto_Unitario = if((xPercentual_Desconto>0 or xPercentual_Desconto<0) and T004_Valor_Preco_Original>0,T004_Valor_Preco_Original*xPercentual_Desconto,0),

             T004_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T004_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

             T004_Valor_Desconto_Unitario_Confirmado = if(xPercentual_Desconto_Confirmado>0 or xPercentual_Desconto_Confirmado<0,T004_Valor_Preco_Original*xPercentual_Desconto_Confirmado,0),

             T004_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0 OR (D009_Valor_Custo_Tabela > 0 AND xD070_Data_Vencimento > CURRENT_DATE()), T004_Valor_Desconto_Unitario*T004_Quantidade, 0),

             T004_Valor_Total_Desconto_Confirmado=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0, T004_Valor_Desconto_Unitario_Confirmado*T004_Quantidade, 0),

             T004_Valor_Preco_Unitario = if(T004_Valor_Preco_Original>0,round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario,xT003_Casas_Decimais_Preco),T004_Valor_Preco_Unitario),

             T004_Valor_Preco_Bruto = round(T004_Valor_Preco_Original_Bruto - T004_Valor_Desconto_Unitario_Bruto,xT003_Casas_Decimais_Preco),

             T004_Valor_Preco_Unitario_Confirmado = round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario_Confirmado,xT003_Casas_Decimais_Preco),

             T004_Valor_Total_Preco = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario*T004_Quantidade,2),T004_Valor_Preco_Unitario*T004_Quantidade),

             T004_Valor_Total_Preco_Confirmado = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada,2), T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada),

             T004_Valor_Total_Preco_Sem_Desconto =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade,2),T004_Valor_Preco_Original * T004_Quantidade),

             T004_Valor_Total_Preco_Sem_Desconto_Confirmado =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade_Confirmada,2), T004_Valor_Preco_Original * T004_Quantidade_Confirmada),

             T004_Valor_Total_Agregados=xValor_Total_Agregados,

             T004_Aliquota_PIS=if(T004_Flag_Isento_PIS='S',0,T004_Aliquota_PIS),

             T004_Aliquota_COFINS=if(T004_Flag_Isento_COFINS='S',0,T004_Aliquota_COFINS),

             T004_Valor_Base_PIS=if(T004_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_PIS=if(T004_Aliquota_PIS>0,T004_Valor_Base_PIS*(T004_Aliquota_PIS/100),0),

             T004_Valor_Base_COFINS=if(T004_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_COFINS=if(T004_Aliquota_COFINS>0,T004_Valor_Base_COFINS*(T004_Aliquota_COFINS/100),0),

             T004_Aliquota_IRPJ=if(T004_Flag_Isento_IRPJ='S',0,T004_Aliquota_IRPJ),

             T004_Aliquota_CSLL=if(T004_Flag_Isento_CSLL='S',0,T004_Aliquota_CSLL),

             T004_Valor_Base_IRPJ=if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco),

             T004_Valor_IRPJ=if(T004_Aliquota_IRPJ>0,T004_Valor_Base_IRPJ*(T004_Aliquota_IRPJ/100),0),

             T004_Valor_Base_CSLL=if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco),

             T004_Valor_CSLL=if(T004_Aliquota_CSLL>0,T004_Valor_Base_CSLL*(T004_Aliquota_CSLL/100),0),

             T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;



       SELECT (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade),

                 (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade_Confirmada),

                 T003_Flag_Revenda_Consumidor

        INTO xMultiplicador_Despesa,

              xMultiplicador_Despesa_Confirmado,

              xFlag_Revenda_Consumidor

        FROM T003

        LEFT JOIN T004 ON T004_T003_Id=T003_Id

       WHERE T003_Id=xT003_Id

       GROUP BY T003_Id;

       IF xMultiplicador_Despesa IS NULL THEN

           set xMultiplicador_Despesa = 0;

       END IF;

       IF xMultiplicador_Despesa_Confirmado IS NULL THEN

           set xMultiplicador_Despesa_Confirmado = 0;

       END IF;

       

        SELECT COUNT(*) INTO xTotal_Itens FROM T004 WHERE T004_T003_Id = xT003_Id;



    SELECT T003_Valor_Frete/SUM(T004_Valor_Preco_Unitario*T004_Quantidade),

        T003_Valor_Frete,

        T003_Valor_Despesas_Acessorias/SUM(T004_Valor_Preco_Unitario*T004_Quantidade)

    INTO xMultiplicador_Frete,

      xValor_Total_Frete,

      xMultiplicador_Despesas_Acessorias

    FROM T003

    LEFT JOIN T004 ON T004_T003_Id=T003_Id

    WHERE T003_Id=xT003_Id

    GROUP BY T003_Id;



    UPDATE T004 SET T004_Valor_Total_Despesas_Acessorias=T004_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

        T004_Valor_Despesas_Acessorias_Unitario=T004_Valor_Total_Despesas_Acessorias/T004_Quantidade,

        T004_Valor_Frete_Total=IF(xC004_Flag_Rateio_Frete=1,T004_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

        T004_Valor_Frete_Unitario=T004_Valor_Frete_Total/T004_Quantidade

    WHERE T004_Id=xT004_Id;

       

    UPDATE T004

    SET T004_Valor_Total_Custo=T004_Valor_Custo_Unitario*T004_Quantidade,

                    T004_Valor_Total_Custo_Confirmado=T004_Valor_Custo_Unitario*T004_Quantidade_Confirmada,

                    T004_Peso_Total=T004_Peso_Unitario*T004_Quantidade,

                    T004_Peso_Bruto_Total=T004_Peso_Bruto*T004_Quantidade,

                    T004_Peso_Total_Confirmado=T004_Peso_Unitario*T004_Quantidade_Confirmada,

                    T004_Valor_Total_Despesas=(T004_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T004_Valor_Total_Despesas_Confirmado=T004_Valor_Total_Preco_Confirmado*xMultiplicador_Despesa_Confirmado,

                    T004_Valor_Despesas_Unitario=T004_Valor_Total_Despesas/T004_Quantidade,

                    T004_Valor_Despesas_Unitario_Confirmado=T004_Valor_Total_Despesas_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_IPI=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco)*IF(T004_Percentual_Reducao_IPI>0,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_Base_IPI_Confirmado=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco_Confirmado)*IF(T004_Percentual_Reducao_IPI,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_IPI=T004_Valor_Base_IPI*(T004_Aliquota_IPI/100),

                    T004_Valor_IPI_Confirmado=T004_Valor_Base_IPI_Confirmado*(T004_Aliquota_IPI/100),

                    T004_Valor_Total_Custo_Final=(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Total_Custo_Final_Confirmado=(T004_Valor_Total_Preco_Confirmado+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas_Confirmado,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Custo_Final_Unitario=T004_Valor_Total_Custo_Final/T004_Quantidade,

                    T004_Valor_Custo_Final_Unitario_Confirmado=T004_Valor_Total_Custo_Final_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_ICMS=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Confirmado=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Desonerado=IF(T004_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T004_Valor_Total_Custo_Final-IF(T004_Percentual_Reducao_ICMS>0,T004_Valor_Base_ICMS,0),0),

                    T004_Valor_ICMS=T004_Valor_Base_ICMS*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Confirmado=T004_Valor_Base_ICMS_Confirmado*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Desonerado=T004_Valor_Base_ICMS_Desonerado*(T004_Aliquota_ICMS_Oculto/100),

                    T004_Valor_Base_ST=IF(T004_Flag_ST='S',(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+T004_Valor_IPI)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST=IF(T004_Flag_ST='S',((T004_Valor_Base_ST*IF(T004_Percentual_Reducao_ICMS_ST>0,((100-T004_Percentual_Reducao_ICMS_ST)/100),1))*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST=IF(T004_Valor_ST<0,0,T004_Valor_ST),

                    T004_Valor_Base_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Total_Custo_Final_Confirmado+T004_Valor_Despesas_Unitario_Confirmado+T004_Valor_IPI_Confirmado)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Base_ST_Confirmado*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST_Confirmado=IF(T004_Valor_ST_Confirmado<0,0,T004_Valor_ST_Confirmado),

                    T004_IPV=(T004_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0))/T004_Valor_Custo_Unitario,

                    T004_Percentual_Margem=round((((T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0))-T004_Valor_Custo_Unitario)/

                              (T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0)))*100,2),

                    T004_Valor_Lucro=round((T004_Valor_Total_Custo*T004_IPV)-(T004_Valor_Total_Custo*T004_IPV_Sem_Lucro),2),

                    T004_Total_Cubagem = IFNULL(T004_Cubagem_Unitaria, 0) * IFNULL(T004_Quantidade,0),

                    T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;

       CALL T003_Gravar_Totalizacao_3(xT003_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T004_Gravar_Totalizacao_4` */

/*!50003 DROP PROCEDURE IF EXISTS  `T004_Gravar_Totalizacao_4` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T004_Gravar_Totalizacao_4`(xT004_Id int(11))
BEGIN

    DECLARE xT003_Id INT;

    DECLARE xPercentual_Desconto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(30,20) DEFAULT 0;

    DECLARE xPercentual_Desconto_Confirmado DECIMAL(30,20) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesa_Confirmado DECIMAL(10,6) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    DECLARE xD006_Flag_Somar_IPI_Base_ICMS varchar(1);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xTotal_Itens INT(5);

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xFlag_ACP VARCHAR(1);

    DECLARE xT003_Casas_Decimais_Preco int(2);

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);

    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Cotacao_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);

    DECLARE xD070_Data_Vencimento date;



      SELECT T004_T003_Id,

           T003_Flag_ACP,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_ST,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto/100,

           T004_Percentual_Desconto_Bruto/100,

           T004_C004_Id,

           T003_Casas_Decimais_Preco,

           D006_Flag_Isento_ICMS

      INTO xT003_Id,

           xFLag_ACP,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_ST,

           xPercentual_Desconto,

           xPercentual_Desconto_Confirmado,

           xPercentual_Desconto_Bruto,

           xC004_Id,

           xT003_Casas_Decimais_Preco,

           xD006_Flag_Isento_ICMS

      FROM T004

      LEFT JOIN D006 ON D006_Id=T004_D006_Id

      LEFT JOIN T003 ON T003_Id=T004_T003_Id

      WHERE T004_Id=xT004_Id;



      SELECT C004_Casas_Decimais_Preco,

           C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

           xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



      SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;

      SELECT C031_Valor INTO xC031_Desabilitar_Cotacao_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCotacaoEmergencia' AND C031_C004_Id = xC004_Id;



      if !(xPercentual_Desconto>0 OR xPercentual_Desconto<0) THEN

         SELECT T003_Percentual_Desconto/100,

                T003_Percentual_Desconto_Confirmado/100

           INTO xPercentual_Desconto,

                xPercentual_Desconto_Confirmado

         FROM T003

         LEFT JOIN C004 ON C004_Id=T003_C004_Id

         WHERE T003_Id=xT003_Id;

      END IF;



      SELECT SUM(T202_Valor_Unitario) INTO xValor_Total_Agregados FROM T202 WHERE T202_T004_Id=xT004_Id;



      IF xPercentual_Desconto IS NULL THEN

         set xPercentual_Desconto = 0;

      END IF;

      IF xPercentual_Desconto_Bruto IS NULL THEN

         set xPercentual_Desconto_Bruto = 0;

      END IF;

       IF xPercentual_Desconto_Confirmado IS NULL THEN

         set xPercentual_Desconto_Confirmado = 0;

      END IF;



      SELECT IFNULL(D070_Data_Vencimento,'0000-00-00')

        INTO xD070_Data_Vencimento

      FROM D070

      LEFT JOIN D069 ON D070_Id=D069_D070_Id

      LEFT JOIN D009 ON D009_Id=D009_D069_Id

      LEFT JOIN T004 ON D009_Id=T004_D009_Id

      WHERE T004_Id=xT004_Id;



      UPDATE T004

      LEFT JOIN D009 ON D009_Id=T004_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id      

         SET T004_Valor_Desconto_Unitario = if((xPercentual_Desconto>0 or xPercentual_Desconto<0) and T004_Valor_Preco_Original>0,T004_Valor_Preco_Original*xPercentual_Desconto,0),

             T004_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T004_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

             T004_Valor_Desconto_Unitario_Confirmado = if(xPercentual_Desconto_Confirmado>0 or xPercentual_Desconto_Confirmado<0,T004_Valor_Preco_Original*xPercentual_Desconto_Confirmado,0),

             T004_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0 OR (D009_Valor_Custo_Tabela > 0 AND xD070_Data_Vencimento > CURRENT_DATE()), T004_Valor_Desconto_Unitario*T004_Quantidade, 0),

             T004_Valor_Total_Desconto_Confirmado=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Cotacao_Emergencia='S' OR (D009_Quantidade_Estoque+D009_Quantidade_OC) >= T004_Quantidade OR T004_T219_Id > 0, T004_Valor_Desconto_Unitario_Confirmado*T004_Quantidade, 0),

             T004_Valor_Preco_Unitario = if(T004_Valor_Preco_Original>0,round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario,xT003_Casas_Decimais_Preco),T004_Valor_Preco_Unitario),

             T004_Valor_Preco_Bruto = round(T004_Valor_Preco_Original_Bruto - T004_Valor_Desconto_Unitario_Bruto,xT003_Casas_Decimais_Preco),

             T004_Valor_Preco_Unitario_Confirmado = round(T004_Valor_Preco_Original - T004_Valor_Desconto_Unitario_Confirmado,xT003_Casas_Decimais_Preco),

             T004_Valor_Total_Preco = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario*T004_Quantidade,2),T004_Valor_Preco_Unitario*T004_Quantidade),

             T004_Valor_Total_Preco_Confirmado = if(xFLag_ACP=4,truncate(T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada,2), T004_Valor_Preco_Unitario_Confirmado*T004_Quantidade_Confirmada),

             T004_Valor_Total_Preco_Sem_Desconto =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade,2),T004_Valor_Preco_Original * T004_Quantidade),

             T004_Valor_Total_Preco_Sem_Desconto_Confirmado =  if(xFLag_ACP=4,truncate(T004_Valor_Preco_Original * T004_Quantidade_Confirmada,2), T004_Valor_Preco_Original * T004_Quantidade_Confirmada),

             T004_Valor_Total_Agregados=xValor_Total_Agregados,

             T004_Aliquota_PIS=if(T004_Flag_Isento_PIS='S',0,T004_Aliquota_PIS),

             T004_Aliquota_COFINS=if(T004_Flag_Isento_COFINS='S',0,T004_Aliquota_COFINS),

             T004_Valor_Base_PIS=if(T004_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_PIS=if(T004_Aliquota_PIS>0,T004_Valor_Base_PIS*(T004_Aliquota_PIS/100),0),

             T004_Valor_Base_COFINS=if(T004_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado-T004_Valor_Total_Custo_Confirmado,T004_Valor_Total_Preco-T004_Valor_Total_Custo),if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco))),

             T004_Valor_COFINS=if(T004_Aliquota_COFINS>0,T004_Valor_Base_COFINS*(T004_Aliquota_COFINS/100),0),

             T004_Aliquota_IRPJ=if(T004_Flag_Isento_IRPJ='S',0,T004_Aliquota_IRPJ),

             T004_Aliquota_CSLL=if(T004_Flag_Isento_CSLL='S',0,T004_Aliquota_CSLL),

             T004_Valor_Base_IRPJ=if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco),

             T004_Valor_IRPJ=if(T004_Aliquota_IRPJ>0,T004_Valor_Base_IRPJ*(T004_Aliquota_IRPJ/100),0),

             T004_Valor_Base_CSLL=if(T004_Quantidade_Confirmada>0,T004_Valor_Total_Preco_Confirmado,T004_Valor_Total_Preco),

             T004_Valor_CSLL=if(T004_Aliquota_CSLL>0,T004_Valor_Base_CSLL*(T004_Aliquota_CSLL/100),0),

             T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;



       SELECT (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade),

                 (if (T003_Flag_Frete=1,T003_Valor_Frete,0)+T003_Valor_Despesas_Acessorias)/sum(T004_Valor_Preco_Unitario*T004_Quantidade_Confirmada),

                 T003_Flag_Revenda_Consumidor

        INTO xMultiplicador_Despesa,

              xMultiplicador_Despesa_Confirmado,

              xFlag_Revenda_Consumidor

        FROM T003

        LEFT JOIN T004 ON T004_T003_Id=T003_Id

       WHERE T003_Id=xT003_Id

       GROUP BY T003_Id;

       IF xMultiplicador_Despesa IS NULL THEN

           set xMultiplicador_Despesa = 0;

       END IF;

       IF xMultiplicador_Despesa_Confirmado IS NULL THEN

           set xMultiplicador_Despesa_Confirmado = 0;

       END IF;

       

        SELECT COUNT(*) INTO xTotal_Itens FROM T004 WHERE T004_T003_Id = xT003_Id;



    SELECT T003_Valor_Frete/SUM(T004_Valor_Preco_Unitario*T004_Quantidade),

        T003_Valor_Frete,

        T003_Valor_Despesas_Acessorias/SUM(T004_Valor_Preco_Unitario*T004_Quantidade)

    INTO xMultiplicador_Frete,

      xValor_Total_Frete,

      xMultiplicador_Despesas_Acessorias

    FROM T003

    LEFT JOIN T004 ON T004_T003_Id=T003_Id

    WHERE T003_Id=xT003_Id

    GROUP BY T003_Id;



    UPDATE T004 SET T004_Valor_Total_Despesas_Acessorias=T004_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

        T004_Valor_Despesas_Acessorias_Unitario=T004_Valor_Total_Despesas_Acessorias/T004_Quantidade,

        T004_Valor_Frete_Total=IF(xC004_Flag_Rateio_Frete=1,T004_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

        T004_Valor_Frete_Unitario=T004_Valor_Frete_Total/T004_Quantidade

    WHERE T004_Id=xT004_Id;

       

    UPDATE T004

    SET T004_Valor_Total_Custo=T004_Valor_Custo_Unitario*T004_Quantidade,

                    T004_Valor_Total_Custo_Confirmado=T004_Valor_Custo_Unitario*T004_Quantidade_Confirmada,

                    T004_Peso_Total=T004_Peso_Unitario*T004_Quantidade,

                    T004_Peso_Bruto_Total=T004_Peso_Bruto*T004_Quantidade,

                    T004_Peso_Total_Confirmado=T004_Peso_Unitario*T004_Quantidade_Confirmada,

                    T004_Valor_Total_Despesas=(T004_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T004_Valor_Total_Despesas_Confirmado=T004_Valor_Total_Preco_Confirmado*xMultiplicador_Despesa_Confirmado,

                    T004_Valor_Despesas_Unitario=T004_Valor_Total_Despesas/T004_Quantidade,

                    T004_Valor_Despesas_Unitario_Confirmado=T004_Valor_Total_Despesas_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_IPI=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco)*IF(T004_Percentual_Reducao_IPI>0,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_Base_IPI_Confirmado=IF(T004_Aliquota_IPI>0,(T004_Valor_Total_Preco_Confirmado)*IF(T004_Percentual_Reducao_IPI,(T004_Percentual_Reducao_IPI/100),1),0),

                    T004_Valor_IPI=T004_Valor_Base_IPI*(T004_Aliquota_IPI/100),

                    T004_Valor_IPI_Confirmado=T004_Valor_Base_IPI_Confirmado*(T004_Aliquota_IPI/100),

                    T004_Valor_Total_Custo_Final=(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Total_Custo_Final_Confirmado=(T004_Valor_Total_Preco_Confirmado+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas_Confirmado,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T004_Valor_IPI,0)),

                    T004_Valor_Custo_Final_Unitario=T004_Valor_Total_Custo_Final/T004_Quantidade,

                    T004_Valor_Custo_Final_Unitario_Confirmado=T004_Valor_Total_Custo_Final_Confirmado/T004_Quantidade_Confirmada,

                    T004_Valor_Base_ICMS=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Confirmado=IF(T004_Aliquota_ICMS>0,T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1),0),

                    T004_Valor_Base_ICMS_Desonerado=IF(T004_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T004_Valor_Total_Custo_Final-IF(T004_Percentual_Reducao_ICMS>0,T004_Valor_Base_ICMS,0),0),

                    T004_Valor_ICMS=T004_Valor_Base_ICMS*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Confirmado=T004_Valor_Base_ICMS_Confirmado*(T004_Aliquota_ICMS/100),

                    T004_Valor_ICMS_Desonerado=T004_Valor_Base_ICMS_Desonerado*(T004_Aliquota_ICMS_Oculto/100),

                    T004_Valor_Base_ST=IF(T004_Flag_ST='S',(T004_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T004_Valor_Total_Despesas,0)+T004_Valor_IPI)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST=IF(T004_Flag_ST='S',((T004_Valor_Base_ST*IF(T004_Percentual_Reducao_ICMS_ST>0,((100-T004_Percentual_Reducao_ICMS_ST)/100),1))*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST=IF(T004_Valor_ST<0,0,T004_Valor_ST),

                    T004_Valor_Base_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Total_Custo_Final_Confirmado+T004_Valor_Despesas_Unitario_Confirmado+T004_Valor_IPI_Confirmado)*((T004_ST_VA/100)+1),0),

                    T004_Valor_ST_Confirmado=IF(T004_Flag_ST='S',(T004_Valor_Base_ST_Confirmado*(T004_ST_ICMS_Interno/100))-((T004_Valor_Total_Custo_Final_Confirmado*IF(T004_Percentual_Reducao_ICMS>0,((100-T004_Percentual_Reducao_ICMS)/100),1))*(T004_ICMS_Inter_Estadual/100)),0),

                    T004_Valor_ST_Confirmado=IF(T004_Valor_ST_Confirmado<0,0,T004_Valor_ST_Confirmado),

                    T004_IPV=(T004_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                              IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0))/T004_Valor_Custo_Unitario,

                    T004_Percentual_Margem=round((((T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0))-T004_Valor_Custo_Unitario)/

                              (T004_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T004_Valor_ICMS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T004_Valor_PIS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T004_Valor_COFINS/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T004_Valor_IRPJ/T004_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T004_Valor_CSLL/T004_Quantidade,0), 0)))*100,2),

                    T004_Valor_Lucro=round((T004_Valor_Total_Custo*T004_IPV)-(T004_Valor_Total_Custo*T004_IPV_Sem_Lucro),2),

                    T004_Total_Cubagem = IFNULL(T004_Cubagem_Unitaria, 0) * IFNULL(T004_Quantidade,0),

                    T004_Valor_Trib_Transparencia=IFNULL(T004_Valor_Total_Preco,0)*(IFNULL(T004_Percentual_Trib_Transparencia,0)/100)

       WHERE T004_Id=xT004_Id;

       CALL T003_Gravar_Totalizacao_3(xT003_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T005_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `T005_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`e000`@`%` PROCEDURE `T005_Gravar_Totalizacao`(xT005_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;
    DECLARE xValor_Total_COFINS decimal(10,2) default 0;
    SELECT sum(T006_Valor_Total_Custo),
           sum(T006_Valor_Total_Preco),
           sum(T006_Valor_Total_Preco_Sem_Desconto),
           sum(T006_Valor_Total_Custo_Final),
           sum(T006_Valor_Total_Desconto),
           sum(T006_Valor_ICMS),
           sum(T006_Valor_Base_ICMS),
           sum(T006_Valor_IPI),
           sum(T006_Valor_Base_IPI),
           sum(T006_Peso_Total),
           sum(T006_Valor_Base_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao_Retencao),
           sum(T006_Valor_PIS),
           sum(T006_Valor_COFINS)
      INTO xValor_Total_Custo,
           xValor_Total_Preco,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Custo_Final,
           xValor_Total_Desconto,
           xValor_ICMS,
           xValor_Base_ICMS,
           xValor_IPI,
           xValor_Base_IPI,
           xPeso_Total,
           xValor_Base_ICMS_Substituicao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Substituicao_Retencao,
           xValor_Total_PIS,
           xValor_Total_COFINS
           FROM T006
           WHERE T006_T005_Id=xT005_Id and T006_Flag_Status!=3;
    UPDATE T005 SET T005_Peso_Total=ifnull(xPeso_Total,0),
                    T005_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),
                    T005_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),
                    T005_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T005_Valor_Desconto,
                    T005_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),
                    T005_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),
                    T005_Valor_Total_ICMS=ifnull(xValor_ICMS,0),
                    T005_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),
                    T005_Valor_Total_IPI=ifnull(xValor_IPI,0),
                    T005_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),
                    T005_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),
                    T005_Valor_ISS=if(T005_Aliquota_ISS>0,T005_Valor_Mao_Obra*(T005_Aliquota_ISS/100),0),
                    T005_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),
                    T005_Valor_Total=ifnull(T005_Valor_Total_Produtos,0)+
                                     ifnull(T005_Valor_Mao_Obra,0)+
                                     ifnull(T005_Valor_Despesas_Acessorias,0)+
                                     ifnull(T005_Valor_ICMS_Substituicao_Retencao,0)+
                                     ifnull(T005_Valor_Total_IPI,0)+
                                     ifnull(T005_Valor_Frete,0),
                    T005_IPV=T005_IPV_Medio(xT005_Id,1),
                    T005_IPV_Normal=T005_IPV_Medio(xT005_Id,2)
              WHERE T005_Id=xT005_Id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `T005_Gravar_Totalizacao_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `T005_Gravar_Totalizacao_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T005_Gravar_Totalizacao_3`(xT005_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Desonerado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Oculto DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Oculto DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;
    DECLARE xValor_Total_COFINS decimal(10,2) default 0;
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    DECLARE xPercentual_Estoque_Disponivel DECIMAL(15,2) DEFAULT 0;
    DECLARE xC004_Id int(10);
    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);
    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);
    DECLARE xC031_Desabilitar_Compra_Emergencia varchar(1);
    DECLARE xFlagItensPendentePedido int(10);
    DECLARE xValor_IRPJ DECIMAL(10,2);
    DECLARE xValor_Base_IRPJ DECIMAL(10,2);
    DECLARE xValor_CSLL DECIMAL(10,2);
    DECLARE xValor_Base_CSLL DECIMAL(10,2);

    SELECT sum(T006_Valor_Total_Custo),
           sum(T006_Valor_Total_Preco),
           sum(T006_Valor_Total_Preco_Sem_Desconto),
           sum(T006_Valor_Total_Custo_Final),
           sum(T006_Valor_Total_Desconto),
           sum(T006_Valor_ICMS),
           sum(T006_Valor_ICMS_Desonerado),
           sum(T006_Valor_Base_ICMS),
           sum(T006_Valor_ICMS_Oculto),
           sum(T006_Valor_Base_ICMS_Oculto),
           sum(T006_Valor_Total_Agregados),
           sum(T006_Valor_IPI),
           sum(T006_Valor_Base_IPI),
           sum(T006_Peso_Total),
           sum(T006_Peso_Bruto_Total),
           sum(T006_Valor_Base_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao_Retencao),
           sum(T006_Valor_PIS),
           sum(T006_Valor_COFINS),
           sum(T006_Valor_Preco_Bruto),
           sum(T006_Total_Cubagem),
           sum(T006_Valor_Trib_Transparencia),
           SUM(IF((IF(T006_Quantidade_Estoque < 0, 0, T006_Quantidade_Estoque)/T006_Quantidade)*100 > 100, 100, (IF(T006_Quantidade_Estoque < 0, 0, T006_Quantidade_Estoque)/T006_Quantidade)*100))/COUNT(T006_Id),
           SUM(T006_Valor_IRPJ),
           SUM(T006_Valor_Base_IRPJ),
           SUM(T006_Valor_CSLL),
           SUM(T006_Valor_Base_CSLL)
      INTO xValor_Total_Custo,
           xValor_Total_Preco,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Custo_Final,
           xValor_Total_Desconto,
           xValor_ICMS,
           xValor_ICMS_Desonerado,
           xValor_Base_ICMS,
           xValor_ICMS_Oculto,
           xValor_Base_ICMS_Oculto,
           xValor_Total_Agregados,
           xValor_IPI,
           xValor_Base_IPI,
           xPeso_Total,
           xPeso_Bruto_Total,
           xValor_Base_ICMS_Substituicao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Substituicao_Retencao,
           xValor_Total_PIS,
           xValor_Total_COFINS,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia,
           xPercentual_Estoque_Disponivel,
           xValor_IRPJ,
           xValor_Base_IRPJ,
           xValor_CSLL,
           xValor_Base_CSLL
           FROM T006
           WHERE T006_T005_Id=xT005_Id and T006_Flag_Status!=3;

    SELECT SUM(T147_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T147
     WHERE T147_T005_Id=xT005_Id;

    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T005_Id=xT005_Id;

    SELECT T005_C004_Id
      INTO xC004_Id     
      FROM T005
     WHERE T005_Id=xT005_Id;

    SELECT IFNULL(COUNT(T006_Id),0)
      INTO xFlagItensPendentePedido
      FROM T006
 LEFT JOIN D009 ON D009_Id=T006_D009_Id
 LEFT JOIN D049 ON D049_Id=D009_D049_Id      
     WHERE (T006_Quantidade_Estoque+T006_Quantidade_OC) < T006_Quantidade 
       AND IFNULL(T006_T219_Id,0) <= 0 
       AND IFNULL(T006_T225_Id,0) <= 0
       AND IFNULL(D049_Flag_Tipo,'') = 'CP'
       AND T006_T005_Id=xT005_Id;

    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Desabilitar_Compra_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCompraEmergencia' AND C031_C004_Id = xC004_Id;

    UPDATE T005 SET T005_Peso_Total=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T005_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T005_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T005_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T005_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),
                    T005_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),
                    T005_Valor_Desconto=IF(xC031_Desabilitar_Compra_Emergencia='S' OR xFlagItensPendentePedido = 0,T005_Valor_Total_Produtos_Sem_Desconto-T005_Valor_Total_Produtos,0),
                    T005_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T005_Valor_Desconto,
                    T005_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),
                    T005_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),
                    T005_Valor_Total_ICMS=ifnull(xValor_ICMS,0),
                    T005_Valor_Total_ICMS_Desonerado=ifnull(xValor_ICMS_Desonerado,0),
                    T005_Valor_Total_Base_ICMS_Oculto=ifnull(xValor_Base_ICMS_Oculto,0),
                    T005_Valor_Total_ICMS_Oculto=ifnull(xValor_ICMS_Oculto,0),
                    T005_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),
                    T005_Valor_Total_IPI=ifnull(xValor_IPI,0),
                    T005_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),
                    T005_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),
                    T005_Valor_ISS=if(T005_Aliquota_ISS>0,T005_Valor_Mao_Obra*(T005_Aliquota_ISS/100),0),
                    T005_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),
                    T005_Valor_Total_Base_IRPJ=xValor_Base_IRPJ,
                    T005_Valor_Total_IRPJ=xValor_IRPJ,
                    T005_Valor_Total_Base_CSLL=xValor_Base_CSLL,
                    T005_Valor_Total_CSLL=xValor_CSLL,
                    T005_Valor_Total=if(T005_Flag_Status=8,0,
                                     ifnull(round(T005_Valor_Total_Produtos,2),0)+
                                     ifnull(T005_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Total_Agregados),0)+
                                     ifnull(T005_Valor_Despesas_Acessorias,0)+
                                     ifnull(round(T005_Valor_ICMS_Substituicao_Retencao,2),0)+
                                     ifnull(round(T005_Valor_Total_IPI,2),0)+
                                     ifnull(T005_Valor_Total_Servicos,0)-
                                     ifnull(T005_Valor_Desconto_Manual,0)-
                                     ifnull(T005_Valor_Troca,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Frete),0)),
                    T005_IPV=if(T005_Valor_Total_Custo>0,(T005_Valor_Total_Produtos-
                                     IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                     IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                     IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                     IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                     IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))/T005_Valor_Total_Custo,0),
                    T005_Percentual_Margem=round((((T005_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))-T005_Valor_Total_Custo)/
                                          (T005_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0)))*100,2),
                    T005_IPV_Normal=ifnull(T005_IPV_Medio(xT005_Id,2),0),
                    T005_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T005_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,
                    T005_Percentual_Estoque_Disponivel=xPercentual_Estoque_Disponivel
              WHERE T005_Id=xT005_Id;

    UPDATE T005 SET T005_Peso_Liquido=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto=ifnull(xPeso_Bruto_Total,0)
                WHERE T005_Id=xT005_Id AND T005_Flag_Totalizar_Peso = 'S';
END */$$
DELIMITER ;

/* Procedure structure for procedure `T005_Gravar_Totalizacao_4` */

/*!50003 DROP PROCEDURE IF EXISTS  `T005_Gravar_Totalizacao_4` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T005_Gravar_Totalizacao_4`(xT005_Id int(11))
BEGIN
    DECLARE xValor_Total_Custo DECIMAL(10,2);
    DECLARE xValor_Total_Preco DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Sem_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Custo_Final DECIMAL(10,2);
    DECLARE xValor_Total_Desconto DECIMAL(10,2);
    DECLARE xValor_Total_Servicos DECIMAL(10,2);
    DECLARE xValor_Total_Trocas DECIMAL(10,2);
    DECLARE xValor_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Desonerado DECIMAL(10,2);
    DECLARE xValor_Base_ICMS DECIMAL(10,2);
    DECLARE xValor_ICMS_Oculto DECIMAL(10,2);
    DECLARE xValor_Base_ICMS_Oculto DECIMAL(10,2);
    DECLARE xValor_Total_Agregados DECIMAL(10,2);
    DECLARE xValor_IPI DECIMAL(10,2);
    DECLARE xValor_Base_IPI DECIMAL(10,2);
    DECLARE xValor_Total_Preco_Bruto DECIMAL(10,2);
    DECLARE xIPV DECIMAL(10,4);
    DECLARE xPeso_Total DECIMAL(10,3);
    DECLARE xPeso_Bruto_Total DECIMAL(10,3);
    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(10,2) DEFAULT 0;
    DECLARE xValor_Total_PIS decimal(10,2) DEFAULT 0;
    DECLARE xValor_Total_COFINS decimal(10,2) default 0;
    DECLARE xValor_Total_Cubagem DECIMAL(10,3) default 0;
    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;
    DECLARE xPercentual_Estoque_Disponivel DECIMAL(15,2) DEFAULT 0;
    DECLARE xC004_Id int(10);
    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);
    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);
    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);
    DECLARE xC031_Desabilitar_Compra_Emergencia varchar(1);
    DECLARE xFlagItensPendentePedido int(10);
    DECLARE xValor_IRPJ DECIMAL(10,2);
    DECLARE xValor_Base_IRPJ DECIMAL(10,2);
    DECLARE xValor_CSLL DECIMAL(10,2);
    DECLARE xValor_Base_CSLL DECIMAL(10,2);

    SELECT sum(T006_Valor_Total_Custo),
           sum(T006_Valor_Total_Preco),
           sum(T006_Valor_Total_Preco_Sem_Desconto),
           sum(T006_Valor_Total_Custo_Final),
           sum(T006_Valor_Total_Desconto),
           sum(T006_Valor_ICMS),
           sum(T006_Valor_ICMS_Desonerado),
           sum(T006_Valor_Base_ICMS),
           sum(T006_Valor_ICMS_Oculto),
           sum(T006_Valor_Base_ICMS_Oculto),
           sum(T006_Valor_Total_Agregados),
           sum(T006_Valor_IPI),
           sum(T006_Valor_Base_IPI),
           sum(T006_Peso_Total),
           sum(T006_Peso_Bruto_Total),
           sum(T006_Valor_Base_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao),
           sum(T006_Valor_ICMS_Substituicao_Retencao),
           sum(T006_Valor_PIS),
           sum(T006_Valor_COFINS),
           sum(T006_Valor_Preco_Bruto),
           sum(T006_Total_Cubagem),
           sum(T006_Valor_Trib_Transparencia),
           SUM(IF((IF(T006_Quantidade_Estoque < 0, 0, T006_Quantidade_Estoque)/T006_Quantidade)*100 > 100, 100, (IF(T006_Quantidade_Estoque < 0, 0, T006_Quantidade_Estoque)/T006_Quantidade)*100))/COUNT(T006_Id),
           SUM(T006_Valor_IRPJ),
           SUM(T006_Valor_Base_IRPJ),
           SUM(T006_Valor_CSLL),
           SUM(T006_Valor_Base_CSLL)
      INTO xValor_Total_Custo,
           xValor_Total_Preco,
           xValor_Total_Preco_Sem_Desconto,
           xValor_Total_Custo_Final,
           xValor_Total_Desconto,
           xValor_ICMS,
           xValor_ICMS_Desonerado,
           xValor_Base_ICMS,
           xValor_ICMS_Oculto,
           xValor_Base_ICMS_Oculto,
           xValor_Total_Agregados,
           xValor_IPI,
           xValor_Base_IPI,
           xPeso_Total,
           xPeso_Bruto_Total,
           xValor_Base_ICMS_Substituicao,
           xValor_ICMS_Substituicao,
           xValor_ICMS_Substituicao_Retencao,
           xValor_Total_PIS,
           xValor_Total_COFINS,
           xValor_Total_Preco_Bruto,
           xValor_Total_Cubagem,
           xValor_Trib_Transparencia,
           xPercentual_Estoque_Disponivel,
           xValor_IRPJ,
           xValor_Base_IRPJ,
           xValor_CSLL,
           xValor_Base_CSLL
           FROM T006
           WHERE T006_T005_Id=xT005_Id and T006_Flag_Status!=3;

    SELECT SUM(T147_Valor_Unitario)
      INTO xValor_Total_Servicos
      FROM T147
     WHERE T147_T005_Id=xT005_Id;

    SELECT SUM(T138_Valor_Preco_Unitario*T138_Quantidade)
      INTO xValor_Total_Trocas
      FROM T138
     WHERE T138_T005_Id=xT005_Id;

    SELECT T005_C004_Id
      INTO xC004_Id     
      FROM T005
     WHERE T005_Id=xT005_Id;

    SELECT IFNULL(COUNT(T006_Id),0)
      INTO xFlagItensPendentePedido
      FROM T006
 LEFT JOIN D009 ON D009_Id=T006_D009_Id
 LEFT JOIN D049 ON D049_Id=D009_D049_Id      
     WHERE (T006_Quantidade_Estoque+T006_Quantidade_OC) < T006_Quantidade 
       AND IFNULL(T006_T219_Id,0) <= 0 
       AND IFNULL(T006_T225_Id,0) <= 0
       AND IFNULL(D049_Flag_Tipo,'') = 'CP'
       AND T006_T005_Id=xT005_Id;

    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;
    SELECT C031_Valor INTO xC031_Desabilitar_Compra_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCompraEmergencia' AND C031_C004_Id = xC004_Id;

    UPDATE T005 SET T005_Peso_Total=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto_Total=ifnull(xPeso_Bruto_Total,0),
                    T005_Valor_Total_Servicos=ifnull(xValor_Total_Servicos,0),
                    T005_Valor_Troca=ifnull(xValor_Total_Trocas,0),
                    T005_Valor_Total_Agregados=ifnull(xValor_Total_Agregados,0),
                    T005_Valor_Total_Produtos=ifnull(xValor_Total_Preco,0),
                    T005_Valor_Total_Produtos_Sem_Desconto=ifnull(xValor_Total_Preco_Sem_Desconto,0),
                    T005_Valor_Desconto=IF(xC031_Desabilitar_Compra_Emergencia='S' OR xFlagItensPendentePedido = 0,T005_Valor_Total_Produtos_Sem_Desconto-T005_Valor_Total_Produtos,0),
                    T005_Valor_Total_Custo_Final=ifnull(xValor_Total_Custo_Final,0)-T005_Valor_Desconto,
                    T005_Valor_Total_Custo=ifnull(xValor_Total_Custo,0),
                    T005_Valor_Total_Base_ICMS=ifnull(xValor_Base_ICMS,0),
                    T005_Valor_Total_ICMS=ifnull(xValor_ICMS,0),
                    T005_Valor_Total_ICMS_Desonerado=ifnull(xValor_ICMS_Desonerado,0),
                    T005_Valor_Total_Base_ICMS_Oculto=ifnull(xValor_Base_ICMS_Oculto,0),
                    T005_Valor_Total_ICMS_Oculto=ifnull(xValor_ICMS_Oculto,0),
                    T005_Valor_Total_Base_IPI=ifnull(xValor_Base_IPI,0),
                    T005_Valor_Total_IPI=ifnull(xValor_IPI,0),
                    T005_Valor_Total_PIS=ifnull(xValor_Total_PIS,0),
                    T005_Valor_Total_COFINS=ifnull(xValor_Total_COFINS,0),
                    T005_Valor_ISS=if(T005_Aliquota_ISS>0,T005_Valor_Mao_Obra*(T005_Aliquota_ISS/100),0),
                    T005_Valor_Base_ICMS_Substituicao=ifnull(xValor_Base_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao=ifnull(xValor_ICMS_Substituicao,0),
                    T005_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0),
                    T005_Valor_Total_Base_IRPJ=xValor_Base_IRPJ,
                    T005_Valor_Total_IRPJ=xValor_IRPJ,
                    T005_Valor_Total_Base_CSLL=xValor_Base_CSLL,
                    T005_Valor_Total_CSLL=xValor_CSLL,
                    T005_Valor_Total=if(T005_Flag_Status=8,0,
                                     ifnull(round(T005_Valor_Total_Produtos,2),0)+
                                     ifnull(T005_Valor_Mao_Obra,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Total_Agregados),0)+
                                     ifnull(T005_Valor_Despesas_Acessorias,0)+
                                     ifnull(round(T005_Valor_ICMS_Substituicao_Retencao,2),0)+
                                     ifnull(round(T005_Valor_Total_IPI,2),0)+
                                     ifnull(T005_Valor_Total_Servicos,0)-
                                     ifnull(T005_Valor_Desconto_Manual,0)-
                                     ifnull(T005_Valor_Troca,0)+
                                     ifnull(if(xValor_Total_Preco_Bruto>0,0,T005_Valor_Frete),0)),
                    T005_IPV=if(T005_Valor_Total_Custo>0,(T005_Valor_Total_Produtos-
                                     IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                     IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                     IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                     IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                     IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))/T005_Valor_Total_Custo,0),
                    T005_Percentual_Margem=round((((T005_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))-T005_Valor_Total_Custo)/
                                          (T005_Valor_Total_Produtos-
                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T005_Valor_Total_ICMS,0), 0)-
                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_Total_PIS,0), 0)-
                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_Total_COFINS,0), 0)-
                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-
                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0)))*100,2),
                    T005_IPV_Normal=ifnull(T005_IPV_Medio(xT005_Id,2),0),
                    T005_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0),
                    T005_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,
                    T005_Percentual_Estoque_Disponivel=xPercentual_Estoque_Disponivel
              WHERE T005_Id=xT005_Id;

    UPDATE T005 SET T005_Peso_Liquido=ifnull(xPeso_Total,0),
                    T005_Peso_Bruto=ifnull(xPeso_Bruto_Total,0)
                WHERE T005_Id=xT005_Id AND T005_Flag_Totalizar_Peso = 'S';
END */$$
DELIMITER ;

/* Procedure structure for procedure `T006_Gravar_Totalizacao` */

/*!50003 DROP PROCEDURE IF EXISTS  `T006_Gravar_Totalizacao` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T006_Gravar_Totalizacao`(xT006_Id int(11))
BEGIN

    DECLARE xT005_Id int;

    DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Devolucao VARCHAR(1);

    DECLARE xFlag_Tipo_Devolucao VARCHAR(10);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;

    DECLARE xFlag_ST VARCHAR(3);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xAliquota_ICMS_1 DECIMAL(5,2);



    DECLARE xFlag_ACP varchar(1);



    DECLARE xT134_Id int(10) default '0';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';



    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';

    DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';

    DECLARE xD059_Codigo_ST varchar(3);

    DECLARE xC004_Percentual_PIS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Percentual_COFINS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xTotal_Itens INT(5);

    DECLARE xD049_Flag_Nacional_Importado varchar(1);



    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';



    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    

    DECLARE xT185_Qtd_Separado DECIMAL(20,2) DEFAULT 0;

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Compra_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);



    SELECT ifnull(SUM(T204_Valor_Unitario),0) INTO xValor_Total_Agregados FROM T204 WHERE T204_T006_Id=xT006_Id;

    

    -- GRAVA A CFOP POR ITEM PARA OS QUE AINDA NAO TEM CFOP

    update T006 left join T005 on T005_Id=T006_T005_Id set T006_D006_Id=T005_D006_Id where T006_Id=xT006_Id and T006_D006_Id is null;



    SELECT T006_T005_Id,

           D006_Flag_Venda_Compra_Outros,

           D049_Flag_Nacional_Importado,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Somar_Despesas_Base_ST,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T006_C004_Id,

           T005_Flag_ACP,

           T134_Reducao_Base_ICMS,

           T134_Id,

           T006_Percentual_Desconto_Bruto/100,

           D006_Flag_Isento_ICMS

      INTO xT005_Id,

           xFlag_Venda_Compra_Outros,

           xD049_Flag_Nacional_Importado,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Somar_Despesas_Base_ST,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xC004_Id,

           xFlag_ACP,

           xT134_Reducao_Base_ICMS,

           xT134_Id,

           xPercentual_Desconto_Bruto,

           xD006_Flag_Isento_ICMS

      FROM T006

      LEFT JOIN T005 ON T005_Id=T006_T005_Id

      LEFT JOIN D006 ON D006_Id=T006_D006_Id

      LEFT JOIN T134 ON T134_Id=T005_T134_Id

      LEFT JOIN D024 ON D024_Id=T005_D024_Id

      LEFT JOIN D020 ON D020_Id=D024_D020_Id

      LEFT JOIN D009 ON D009_Id=T006_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

      LEFT JOIN D001 ON D001_Id=D049_D001_Id

     WHERE T006_Id=xT006_Id

     LIMIT 1;



     SELECT COUNT(*) INTO xTotal_Itens FROM T006 WHERE T006_T005_Id = xT005_Id;

     

     SELECT C004_Casas_Decimais_Preco,

             C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

             xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



    SELECT T005_Percentual_Desconto/100,

           T005_Flag_Devolucao,

           T005_Flag_Tipo_Devolucao

      INTO xPercentual_Desconto,

           xFlag_Devolucao,

           xFlag_Tipo_Devolucao

      FROM T005

      LEFT JOIN C004 ON C004_Id=T005_C004_Id

     WHERE T005_Id=xT005_Id;



    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Desabilitar_Compra_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCompraEmergencia' AND C031_C004_Id = xC004_Id;

     

    IF xPercentual_Desconto IS NULL THEN

       set xPercentual_Desconto = 0;

    END IF;   

    

    UPDATE T006 SET T006_Valor_Desconto_Unitario = if(xPercentual_Desconto>0,T006_Valor_Preco_Sem_Desconto_Unitario*xPercentual_Desconto,0),

                    T006_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T006_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T006_Valor_Total_Desconto = T006_Valor_Desconto_Unitario*T006_Quantidade,

                    T006_Valor_Preco_Unitario = round(T006_Valor_Preco_Sem_Desconto_Unitario - T006_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T006_Valor_Total_Preco = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Unitario*T006_Quantidade,2),T006_Valor_Preco_Unitario*T006_Quantidade),

                    T006_Valor_Total_Preco_Sem_Desconto = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Original*T006_Quantidade,2),T006_Valor_Preco_Original*T006_Quantidade),

                    T006_Valor_Preco_Bruto = round(T006_Valor_Preco_Original_Bruto - T006_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco)

              WHERE T006_Id=xT006_Id;



    IF xFlag_Devolucao='S' AND xFlag_Tipo_Devolucao='EMITIDA' THEN

       UPDATE T006 SET T006_Valor_Total_Frete=T006_Valor_Frete_Unitario*T006_Quantidade,

                       T006_Valor_Total_Despesas_Acessorias=T006_Valor_Despesas_Acessorias_Unitario*T006_Quantidade,

                       T006_Valor_Total_Desconto=T006_Valor_Desconto_Unitario*T006_Quantidade

              WHERE T006_T005_Id=xT005_Id;

       SELECT SUM(T006_Valor_Total_Frete),

              SUM(T006_Valor_Total_Despesas_Acessorias),

              SUM(T006_Valor_Total_Desconto)

         INTO xValor_Total_Frete,

              xValor_Total_Despesas_Acessorias,

              xValor_Total_Desconto

         FROM T006

         WHERE T006_T005_Id=xT005_Id

         GROUP BY T006_T005_Id;

         UPDATE T005

         SET T005_Valor_Frete=xValor_Total_Frete,

              T005_Valor_Despesas_Acessorias=xValor_Total_Despesas_Acessorias

         WHERE T005_Id=xT005_Id;

    ELSE

           SELECT T005_Valor_Frete/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

                  T005_Valor_Frete,

                  T005_Valor_Despesas_Acessorias/sum(T006_Valor_Preco_Unitario*T006_Quantidade)

           INTO xMultiplicador_Frete,

                xValor_Total_Frete,

                xMultiplicador_Despesas_Acessorias

         FROM T005

         LEFT JOIN T006 ON T006_T005_Id=T005_Id

         WHERE T005_Id=xT005_Id

         GROUP BY T005_Id;

        UPDATE T006 SET T006_Valor_Total_Despesas_Acessorias=T006_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

                        T006_Valor_Despesas_Acessorias_Unitario=T006_Valor_Total_Despesas_Acessorias/T006_Quantidade,

                        T006_Valor_Total_Frete=IF(xC004_Flag_Rateio_Frete=1,T006_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

                        T006_Valor_Frete_Unitario=T006_Valor_Total_Frete/T006_Quantidade

                  WHERE T006_Id=xT006_Id;

    END IF;

    SELECT (T005_Valor_Frete+T005_Valor_Despesas_Acessorias)/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

           T005_Flag_Revenda_Consumidor

      INTO

        xMultiplicador_Despesa,

        xFlag_Revenda_Consumidor

      FROM T005

      LEFT JOIN T006 ON T006_T005_Id=T005_Id

     WHERE T005_Id=xT005_Id

     GROUP BY T005_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       set xMultiplicador_Despesa = 0;

    END IF;

    UPDATE T006

    LEFT JOIN D009 ON D009_Id=T006_D009_Id

    LEFT JOIN D049 ON D049_Id=D009_D049_Id

                SET T006_Valor_Total_Custo = T006_Valor_Custo_Unitario*T006_Quantidade,

                    T006_Peso_Total = T006_Peso_Unitario*T006_Quantidade,

                    T006_Peso_Bruto_Total = T006_Peso_Bruto*T006_Quantidade,

                    T006_Valor_Total_Despesas=(T006_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T006_Valor_Despesas_Unitario=T006_Valor_Total_Despesas/T006_Quantidade,

                    T006_Valor_Total_Agregados=xValor_Total_Agregados,

                    T006_Valor_Base_IPI=If(T006_Aliquota_IPI>0,(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T006_Valor_Total_Frete+T006_Valor_Total_Despesas_Acessorias,0))*If(T006_Percentual_Reducao_IPI>0,(T006_Percentual_Reducao_IPI/100),1),0),

                    T006_Valor_IPI=T006_Valor_Base_IPI*(T006_Aliquota_IPI/100),

                    T006_Valor_Total_Custo_Final=(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0)),

                    T006_Valor_Custo_Final_Unitario=T006_Valor_Total_Custo_Final/T006_Quantidade,

                    T006_Valor_Base_ICMS=If(T006_Aliquota_ICMS>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1),0),

                    T006_Valor_Base_ICMS_Oculto=If(T006_Aliquota_ICMS_Oculto>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS_Oculto>0,((100-T006_Percentual_Reducao_ICMS_Oculto)/100),1),0),

                    T006_Valor_Base_ICMS_Desonerado=IF(T006_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T006_Valor_Total_Custo_Final-IF(T006_Percentual_Reducao_ICMS>0,T006_Valor_Base_ICMS,0),0),

                    T006_Valor_ICMS=T006_Valor_Base_ICMS*(T006_Aliquota_ICMS/100),

                    T006_Valor_ICMS_Oculto=T006_Valor_Base_ICMS_Oculto*(T006_Aliquota_ICMS_Oculto/100),

                    T006_Valor_ICMS_Desonerado=T006_Valor_Base_ICMS_Desonerado*(T006_Aliquota_ICMS_Oculto/100),                    

                    T006_Valor_Base_ICMS_Substituicao=IF(T006_Flag_ST='S',(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+T006_Valor_IPI)*((T006_ST_VA/100)+1),0),

                    T006_Valor_ICMS_Substituicao=(T006_Valor_Base_ICMS_Substituicao*(T006_ST_ICMS_Interno/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=((T006_Valor_Base_ICMS_Substituicao*if(T006_Percentual_Reducao_ICMS_ST>0,((100-T006_Percentual_Reducao_ICMS_ST)/100),1))*(T006_ST_ICMS_Interno/100))-((T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1))*(T006_ICMS_Inter_Estadual/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=IF(T006_Valor_ICMS_Substituicao_Retencao<0,0,T006_Valor_ICMS_Substituicao_Retencao),

                    T006_Valor_Base_PIS=if(T006_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_PIS=if(T006_Flag_Isento_PIS='S',0,T006_Aliquota_PIS),

                    T006_Valor_PIS=if(T006_Aliquota_PIS>0,T006_Valor_Base_PIS*(T006_Aliquota_PIS/100),0),

                    T006_Valor_Base_COFINS=if(T006_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_COFINS=if(T006_Flag_Isento_COFINS='S',0,T006_Aliquota_COFINS),

                    T006_Valor_COFINS=if(T006_Aliquota_COFINS>0,T006_Valor_Base_COFINS*(T006_Aliquota_COFINS/100),0),

                    T006_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T006_Valor_ICMS_Credito,If(T006_Aliquota_ICMS_Credito>0,(T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))-((T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T006_Aliquota_ICMS_Credito/100)),

                    T006_Total_Cubagem = IFNULL(T006_Cubagem_Unitaria,0) * IFNULL(T006_Quantidade,0),

                    T006_Valor_Trib_Transparencia=IFNULL(T006_Valor_Total_Preco,0)*(IFNULL(T006_Percentual_Trib_Transparencia,0)/100),

                    T006_IPV=(T006_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0))/T006_Valor_Custo_Unitario,

                    T006_Percentual_Margem=round((((T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0))-T006_Valor_Custo_Unitario)/

                              (T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)))*100,2),

                    T006_Valor_Lucro=round((T006_Valor_Total_Custo*T006_IPV)-(T006_Valor_Total_Custo*T006_IPV_Sem_Lucro),2),

                    T006_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Compra_Emergencia='S' OR (T006_Quantidade_Estoque+T006_Quantidade_OC) >= T006_Quantidade OR T006_T219_Id > 0 OR T006_T225_Id > 0, T006_Valor_Desconto_Unitario*T006_Quantidade, 0)

              WHERE T006_Id=xT006_Id;

    CALL T005_Gravar_Totalizacao_3(xT005_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T006_Gravar_Totalizacao_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `T006_Gravar_Totalizacao_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T006_Gravar_Totalizacao_3`(xT006_Id int(11))
BEGIN

    DECLARE xT005_Id int;

    DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Devolucao VARCHAR(1);

    DECLARE xFlag_Tipo_Devolucao VARCHAR(10);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;

    DECLARE xFlag_ST VARCHAR(3);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xAliquota_ICMS_1 DECIMAL(5,2);



    DECLARE xFlag_ACP varchar(1);



    DECLARE xT134_Id int(10) default '0';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';



    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';

    DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';

    DECLARE xD059_Codigo_ST varchar(3);

    DECLARE xC004_Percentual_PIS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Percentual_COFINS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xTotal_Itens INT(5);

    DECLARE xD049_Flag_Nacional_Importado varchar(1);



    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';



    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    

    DECLARE xT185_Qtd_Separado DECIMAL(20,2) DEFAULT 0;

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);

    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Compra_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);



    SELECT ifnull(SUM(T204_Valor_Unitario),0) INTO xValor_Total_Agregados FROM T204 WHERE T204_T006_Id=xT006_Id;

    

    -- GRAVA A CFOP POR ITEM PARA OS QUE AINDA NAO TEM CFOP

    update T006 left join T005 on T005_Id=T006_T005_Id set T006_D006_Id=T005_D006_Id where T006_Id=xT006_Id and T006_D006_Id is null;



    SELECT T006_T005_Id,

           D006_Flag_Venda_Compra_Outros,

           D049_Flag_Nacional_Importado,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Somar_Despesas_Base_ST,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T006_C004_Id,

           T005_Flag_ACP,

           T134_Reducao_Base_ICMS,

           T134_Id,

           T006_Percentual_Desconto_Bruto/100,

           D006_Flag_Isento_ICMS

      INTO xT005_Id,

           xFlag_Venda_Compra_Outros,

           xD049_Flag_Nacional_Importado,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Somar_Despesas_Base_ST,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xC004_Id,

           xFlag_ACP,

           xT134_Reducao_Base_ICMS,

           xT134_Id,

           xPercentual_Desconto_Bruto,

           xD006_Flag_Isento_ICMS

      FROM T006

      LEFT JOIN T005 ON T005_Id=T006_T005_Id

      LEFT JOIN D006 ON D006_Id=T006_D006_Id

      LEFT JOIN T134 ON T134_Id=T005_T134_Id

      LEFT JOIN D024 ON D024_Id=T005_D024_Id

      LEFT JOIN D020 ON D020_Id=D024_D020_Id

      LEFT JOIN D009 ON D009_Id=T006_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

      LEFT JOIN D001 ON D001_Id=D049_D001_Id

     WHERE T006_Id=xT006_Id

     LIMIT 1;



     SELECT COUNT(*) INTO xTotal_Itens FROM T006 WHERE T006_T005_Id = xT005_Id;

     

     SELECT C004_Casas_Decimais_Preco,

             C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

             xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



    SELECT T005_Percentual_Desconto/100,

           T005_Flag_Devolucao,

           T005_Flag_Tipo_Devolucao

      INTO xPercentual_Desconto,

           xFlag_Devolucao,

           xFlag_Tipo_Devolucao

      FROM T005

      LEFT JOIN C004 ON C004_Id=T005_C004_Id

     WHERE T005_Id=xT005_Id;



    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Desabilitar_Compra_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCompraEmergencia' AND C031_C004_Id = xC004_Id;

     

    IF xPercentual_Desconto IS NULL THEN

       set xPercentual_Desconto = 0;

    END IF;   

    

    UPDATE T006 SET T006_Valor_Desconto_Unitario = if(xPercentual_Desconto>0,T006_Valor_Preco_Sem_Desconto_Unitario*xPercentual_Desconto,0),

                    T006_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T006_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T006_Valor_Total_Desconto = T006_Valor_Desconto_Unitario*T006_Quantidade,

                    T006_Valor_Preco_Unitario = round(T006_Valor_Preco_Sem_Desconto_Unitario - T006_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T006_Valor_Total_Preco = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Unitario*T006_Quantidade,2),T006_Valor_Preco_Unitario*T006_Quantidade),

                    T006_Valor_Total_Preco_Sem_Desconto = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Original*T006_Quantidade,2),T006_Valor_Preco_Original*T006_Quantidade),

                    T006_Valor_Preco_Bruto = round(T006_Valor_Preco_Original_Bruto - T006_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco)

              WHERE T006_Id=xT006_Id;



    IF xFlag_Devolucao='S' AND xFlag_Tipo_Devolucao='EMITIDA' THEN

       UPDATE T006 SET T006_Valor_Total_Frete=T006_Valor_Frete_Unitario*T006_Quantidade,

                       T006_Valor_Total_Despesas_Acessorias=T006_Valor_Despesas_Acessorias_Unitario*T006_Quantidade,

                       T006_Valor_Total_Desconto=T006_Valor_Desconto_Unitario*T006_Quantidade

              WHERE T006_T005_Id=xT005_Id;

       SELECT SUM(T006_Valor_Total_Frete),

              SUM(T006_Valor_Total_Despesas_Acessorias),

              SUM(T006_Valor_Total_Desconto)

         INTO xValor_Total_Frete,

              xValor_Total_Despesas_Acessorias,

              xValor_Total_Desconto

         FROM T006

         WHERE T006_T005_Id=xT005_Id

         GROUP BY T006_T005_Id;

         UPDATE T005

         SET T005_Valor_Frete=xValor_Total_Frete,

              T005_Valor_Despesas_Acessorias=xValor_Total_Despesas_Acessorias

         WHERE T005_Id=xT005_Id;

    ELSE

           SELECT T005_Valor_Frete/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

                  T005_Valor_Frete,

                  T005_Valor_Despesas_Acessorias/sum(T006_Valor_Preco_Unitario*T006_Quantidade)

           INTO xMultiplicador_Frete,

                xValor_Total_Frete,

                xMultiplicador_Despesas_Acessorias

         FROM T005

         LEFT JOIN T006 ON T006_T005_Id=T005_Id

         WHERE T005_Id=xT005_Id

         GROUP BY T005_Id;

        UPDATE T006 SET T006_Valor_Total_Despesas_Acessorias=T006_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

                        T006_Valor_Despesas_Acessorias_Unitario=T006_Valor_Total_Despesas_Acessorias/T006_Quantidade,

                        T006_Valor_Total_Frete=IF(xC004_Flag_Rateio_Frete=1,T006_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

                        T006_Valor_Frete_Unitario=T006_Valor_Total_Frete/T006_Quantidade

                  WHERE T006_Id=xT006_Id;

    END IF;

    SELECT (T005_Valor_Frete+T005_Valor_Despesas_Acessorias)/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

           T005_Flag_Revenda_Consumidor

      INTO

        xMultiplicador_Despesa,

        xFlag_Revenda_Consumidor

      FROM T005

      LEFT JOIN T006 ON T006_T005_Id=T005_Id

     WHERE T005_Id=xT005_Id

     GROUP BY T005_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       set xMultiplicador_Despesa = 0;

    END IF;

    UPDATE T006

    LEFT JOIN D009 ON D009_Id=T006_D009_Id

    LEFT JOIN D049 ON D049_Id=D009_D049_Id

                SET T006_Valor_Total_Custo = T006_Valor_Custo_Unitario*T006_Quantidade,

                    T006_Peso_Total = T006_Peso_Unitario*T006_Quantidade,

                    T006_Peso_Bruto_Total = T006_Peso_Bruto*T006_Quantidade,

                    T006_Valor_Total_Despesas=(T006_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T006_Valor_Despesas_Unitario=T006_Valor_Total_Despesas/T006_Quantidade,

                    T006_Valor_Total_Agregados=xValor_Total_Agregados,

                    T006_Valor_Base_IPI=If(T006_Aliquota_IPI>0,(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T006_Valor_Total_Frete+T006_Valor_Total_Despesas_Acessorias,0))*If(T006_Percentual_Reducao_IPI>0,(T006_Percentual_Reducao_IPI/100),1),0),

                    T006_Valor_IPI=T006_Valor_Base_IPI*(T006_Aliquota_IPI/100),

                    T006_Valor_Total_Custo_Final=(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0)),

                    T006_Valor_Custo_Final_Unitario=T006_Valor_Total_Custo_Final/T006_Quantidade,

                    T006_Valor_Base_ICMS=If(T006_Aliquota_ICMS>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1),0),

                    T006_Valor_Base_ICMS_Oculto=If(T006_Aliquota_ICMS_Oculto>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS_Oculto>0,((100-T006_Percentual_Reducao_ICMS_Oculto)/100),1),0),

                    T006_Valor_Base_ICMS_Desonerado=IF(T006_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T006_Valor_Total_Custo_Final-IF(T006_Percentual_Reducao_ICMS>0,T006_Valor_Base_ICMS,0),0),

                    T006_Valor_ICMS=T006_Valor_Base_ICMS*(T006_Aliquota_ICMS/100),

                    T006_Valor_ICMS_Oculto=T006_Valor_Base_ICMS_Oculto*(T006_Aliquota_ICMS_Oculto/100),

                    T006_Valor_ICMS_Desonerado=T006_Valor_Base_ICMS_Desonerado*(T006_Aliquota_ICMS_Oculto/100),                    

                    T006_Valor_Base_ICMS_Substituicao=IF(T006_Flag_ST='S',(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+T006_Valor_IPI)*((T006_ST_VA/100)+1),0),

                    T006_Valor_ICMS_Substituicao=(T006_Valor_Base_ICMS_Substituicao*(T006_ST_ICMS_Interno/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=((T006_Valor_Base_ICMS_Substituicao*if(T006_Percentual_Reducao_ICMS_ST>0,((100-T006_Percentual_Reducao_ICMS_ST)/100),1))*(T006_ST_ICMS_Interno/100))-((T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1))*(T006_ICMS_Inter_Estadual/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=IF(T006_Valor_ICMS_Substituicao_Retencao<0,0,T006_Valor_ICMS_Substituicao_Retencao),

                    T006_Valor_Base_PIS=if(T006_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_PIS=if(T006_Flag_Isento_PIS='S',0,T006_Aliquota_PIS),

                    T006_Valor_PIS=if(T006_Aliquota_PIS>0,T006_Valor_Base_PIS*(T006_Aliquota_PIS/100),0),

                    T006_Valor_Base_COFINS=if(T006_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_COFINS=if(T006_Flag_Isento_COFINS='S',0,T006_Aliquota_COFINS),

                    T006_Valor_COFINS=if(T006_Aliquota_COFINS>0,T006_Valor_Base_COFINS*(T006_Aliquota_COFINS/100),0),

                    T006_Aliquota_IRPJ=if(T006_Flag_Isento_IRPJ='S',0,T006_Aliquota_IRPJ),

                    T006_Aliquota_CSLL=if(T006_Flag_Isento_CSLL='S',0,T006_Aliquota_CSLL),

                    T006_Valor_Base_IRPJ=T006_Valor_Total_Preco,

                    T006_Valor_IRPJ=if(T006_Aliquota_IRPJ>0,T006_Valor_Base_IRPJ*(T006_Aliquota_IRPJ/100),0),

                    T006_Valor_Base_CSLL=T006_Valor_Total_Preco,

                    T006_Valor_CSLL=if(T006_Aliquota_CSLL>0,T006_Valor_Base_CSLL*(T006_Aliquota_CSLL/100),0),

                    T006_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T006_Valor_ICMS_Credito,If(T006_Aliquota_ICMS_Credito>0,(T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))-((T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T006_Aliquota_ICMS_Credito/100)),

                    T006_Total_Cubagem = IFNULL(T006_Cubagem_Unitaria,0) * IFNULL(T006_Quantidade,0),

                    T006_Valor_Trib_Transparencia=IFNULL(T006_Valor_Total_Preco,0)*(IFNULL(T006_Percentual_Trib_Transparencia,0)/100),

                    T006_IPV=(T006_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0))/T006_Valor_Custo_Unitario,

                    T006_Percentual_Margem=round((((T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0))-T006_Valor_Custo_Unitario)/

                              (T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0)))*100,2),

                    T006_Valor_Lucro=round((T006_Valor_Total_Custo*T006_IPV)-(T006_Valor_Total_Custo*T006_IPV_Sem_Lucro),2),

                    T006_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Compra_Emergencia='S' OR (T006_Quantidade_Estoque+T006_Quantidade_OC) >= T006_Quantidade OR T006_T219_Id > 0 OR T006_T225_Id > 0, T006_Valor_Desconto_Unitario*T006_Quantidade, 0)

              WHERE T006_Id=xT006_Id;

    CALL T005_Gravar_Totalizacao_3(xT005_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T006_Gravar_Totalizacao_4` */

/*!50003 DROP PROCEDURE IF EXISTS  `T006_Gravar_Totalizacao_4` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T006_Gravar_Totalizacao_4`(xT006_Id int(11))
BEGIN

    DECLARE xT005_Id int;

    DECLARE xPercentual_Desconto DECIMAL(20,10) DEFAULT 0;

    DECLARE xPercentual_Desconto_Bruto DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesa DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Despesas_Acessorias DECIMAL(20,10) DEFAULT 0;

    DECLARE xMultiplicador_Frete DECIMAL(20,10) DEFAULT 0;

    DECLARE xFlag_Revenda_Consumidor VARCHAR(1);

    DECLARE xFlag_Devolucao VARCHAR(1);

    DECLARE xFlag_Tipo_Devolucao VARCHAR(10);

    DECLARE xValor_Total_Frete DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Total_Despesas_Acessorias DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Agregados DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(10,2) DEFAULT 0;

    DECLARE xFlag_ST VARCHAR(3);

    DECLARE xFlag_Venda_Compra_Outros VARCHAR(1);

    DECLARE xAliquota_ICMS_1 DECIMAL(5,2);



    DECLARE xFlag_ACP varchar(1);



    DECLARE xT134_Id int(10) default '0';

    DECLARE xT134_Reducao_Base_ICMS decimal(10,2) default '0';



    DECLARE xD006_Flag_Somar_IPI_Base_ICMS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_IPI ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Somar_Despesas_Base_ST ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Flag_Isento_PIS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_PIS VARCHAR(2) default '01';

    DECLARE xD006_Flag_Isento_COFINS ENUM('S','N') DEFAULT 'N';

    DECLARE xD006_Situacao_Tributaria_COFINS VARCHAR(2) default '01';

    DECLARE xD059_Codigo_ST varchar(3);

    DECLARE xC004_Percentual_PIS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Percentual_COFINS decimal(6,2) DEFAULT 0;

    DECLARE xC004_Flag_Rateio_Frete VARCHAR(1) DEFAULT '1';

    DECLARE xTotal_Itens INT(5);

    DECLARE xD049_Flag_Nacional_Importado varchar(1);



    DECLARE xD006_Flag_Forma_Calculo_COFINS varchar(1) default 'V';

    DECLARE xD006_Flag_Forma_Calculo_PIS varchar(1) default 'V';



    DECLARE xC004_Casas_Decimais_Preco int(2);

    DECLARE xC004_Id int(10);

    

    DECLARE xT185_Qtd_Separado DECIMAL(20,2) DEFAULT 0;

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);

    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);

    DECLARE xC031_Desabilitar_Compra_Emergencia varchar(1);

    DECLARE xD006_Flag_Isento_ICMS varchar(1);



    SELECT ifnull(SUM(T204_Valor_Unitario),0) INTO xValor_Total_Agregados FROM T204 WHERE T204_T006_Id=xT006_Id;

    

    -- GRAVA A CFOP POR ITEM PARA OS QUE AINDA NAO TEM CFOP

    update T006 left join T005 on T005_Id=T006_T005_Id set T006_D006_Id=T005_D006_Id where T006_Id=xT006_Id and T006_D006_Id is null;



    SELECT T006_T005_Id,

           D006_Flag_Venda_Compra_Outros,

           D049_Flag_Nacional_Importado,

           D006_Flag_Somar_IPI_Base_ICMS,

           D006_Flag_Somar_Despesas_Base_IPI,

           D006_Flag_Somar_Despesas_Base_ST,

           D006_Flag_Forma_Calculo_COFINS,

           D006_Flag_Forma_Calculo_PIS,

           T006_C004_Id,

           T005_Flag_ACP,

           T134_Reducao_Base_ICMS,

           T134_Id,

           T006_Percentual_Desconto_Bruto/100,

           D006_Flag_Isento_ICMS

      INTO xT005_Id,

           xFlag_Venda_Compra_Outros,

           xD049_Flag_Nacional_Importado,

           xD006_Flag_Somar_IPI_Base_ICMS,

           xD006_Flag_Somar_Despesas_Base_IPI,

           xD006_Flag_Somar_Despesas_Base_ST,

           xD006_Flag_Forma_Calculo_COFINS,

           xD006_Flag_Forma_Calculo_PIS,

           xC004_Id,

           xFlag_ACP,

           xT134_Reducao_Base_ICMS,

           xT134_Id,

           xPercentual_Desconto_Bruto,

           xD006_Flag_Isento_ICMS

      FROM T006

      LEFT JOIN T005 ON T005_Id=T006_T005_Id

      LEFT JOIN D006 ON D006_Id=T006_D006_Id

      LEFT JOIN T134 ON T134_Id=T005_T134_Id

      LEFT JOIN D024 ON D024_Id=T005_D024_Id

      LEFT JOIN D020 ON D020_Id=D024_D020_Id

      LEFT JOIN D009 ON D009_Id=T006_D009_Id

      LEFT JOIN D049 ON D049_Id=D009_D049_Id

      LEFT JOIN D001 ON D001_Id=D049_D001_Id

     WHERE T006_Id=xT006_Id

     LIMIT 1;



     SELECT COUNT(*) INTO xTotal_Itens FROM T006 WHERE T006_T005_Id = xT005_Id;

     

     SELECT C004_Casas_Decimais_Preco,

             C004_Flag_Rateio_Frete

        INTO xC004_Casas_Decimais_Preco,

             xC004_Flag_Rateio_Frete

        FROM C004

       WHERE C004_Id=xC004_Id;



    SELECT T005_Percentual_Desconto/100,

           T005_Flag_Devolucao,

           T005_Flag_Tipo_Devolucao

      INTO xPercentual_Desconto,

           xFlag_Devolucao,

           xFlag_Tipo_Devolucao

      FROM T005

      LEFT JOIN C004 ON C004_Id=T005_C004_Id

     WHERE T005_Id=xT005_Id;



    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Desabilitar_Compra_Emergencia FROM C031 WHERE C031_Campo = 'desabilitarCompraEmergencia' AND C031_C004_Id = xC004_Id;

     

    IF xPercentual_Desconto IS NULL THEN

       set xPercentual_Desconto = 0;

    END IF;   

    

    UPDATE T006 SET T006_Valor_Desconto_Unitario = if(xPercentual_Desconto>0,T006_Valor_Preco_Sem_Desconto_Unitario*xPercentual_Desconto,0),

                    T006_Valor_Desconto_Unitario_Bruto = if(xPercentual_Desconto_Bruto>0 or xPercentual_Desconto_Bruto<0,T006_Valor_Preco_Original_Bruto*xPercentual_Desconto_Bruto,0),

                    T006_Valor_Total_Desconto = T006_Valor_Desconto_Unitario*T006_Quantidade,

                    T006_Valor_Preco_Unitario = round(T006_Valor_Preco_Sem_Desconto_Unitario - T006_Valor_Desconto_Unitario,xC004_Casas_Decimais_Preco),

                    T006_Valor_Total_Preco = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Unitario*T006_Quantidade,2),T006_Valor_Preco_Unitario*T006_Quantidade),

                    T006_Valor_Total_Preco_Sem_Desconto = if(xFlag_ACP=4,truncate(T006_Valor_Preco_Original*T006_Quantidade,2),T006_Valor_Preco_Original*T006_Quantidade),

                    T006_Valor_Preco_Bruto = round(T006_Valor_Preco_Original_Bruto - T006_Valor_Desconto_Unitario_Bruto,xC004_Casas_Decimais_Preco)

              WHERE T006_Id=xT006_Id;



    IF xFlag_Devolucao='S' AND xFlag_Tipo_Devolucao='EMITIDA' THEN

       UPDATE T006 SET T006_Valor_Total_Frete=T006_Valor_Frete_Unitario*T006_Quantidade,

                       T006_Valor_Total_Despesas_Acessorias=T006_Valor_Despesas_Acessorias_Unitario*T006_Quantidade,

                       T006_Valor_Total_Desconto=T006_Valor_Desconto_Unitario*T006_Quantidade

              WHERE T006_T005_Id=xT005_Id;

       SELECT SUM(T006_Valor_Total_Frete),

              SUM(T006_Valor_Total_Despesas_Acessorias),

              SUM(T006_Valor_Total_Desconto)

         INTO xValor_Total_Frete,

              xValor_Total_Despesas_Acessorias,

              xValor_Total_Desconto

         FROM T006

         WHERE T006_T005_Id=xT005_Id

         GROUP BY T006_T005_Id;

         UPDATE T005

         SET T005_Valor_Frete=xValor_Total_Frete,

              T005_Valor_Despesas_Acessorias=xValor_Total_Despesas_Acessorias

         WHERE T005_Id=xT005_Id;

    ELSE

           SELECT T005_Valor_Frete/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

                  T005_Valor_Frete,

                  T005_Valor_Despesas_Acessorias/sum(T006_Valor_Preco_Unitario*T006_Quantidade)

           INTO xMultiplicador_Frete,

                xValor_Total_Frete,

                xMultiplicador_Despesas_Acessorias

         FROM T005

         LEFT JOIN T006 ON T006_T005_Id=T005_Id

         WHERE T005_Id=xT005_Id

         GROUP BY T005_Id;

        UPDATE T006 SET T006_Valor_Total_Despesas_Acessorias=T006_Valor_Total_Preco*xMultiplicador_Despesas_Acessorias,

                        T006_Valor_Despesas_Acessorias_Unitario=T006_Valor_Total_Despesas_Acessorias/T006_Quantidade,

                        T006_Valor_Total_Frete=IF(xC004_Flag_Rateio_Frete=1,T006_Valor_Total_Preco*xMultiplicador_Frete,xValor_Total_Frete/xTotal_Itens),

                        T006_Valor_Frete_Unitario=T006_Valor_Total_Frete/T006_Quantidade

                  WHERE T006_Id=xT006_Id;

    END IF;

    SELECT (T005_Valor_Frete+T005_Valor_Despesas_Acessorias)/sum(T006_Valor_Preco_Unitario*T006_Quantidade),

           T005_Flag_Revenda_Consumidor

      INTO

        xMultiplicador_Despesa,

        xFlag_Revenda_Consumidor

      FROM T005

      LEFT JOIN T006 ON T006_T005_Id=T005_Id

     WHERE T005_Id=xT005_Id

     GROUP BY T005_Id;

    IF xMultiplicador_Despesa IS NULL THEN

       set xMultiplicador_Despesa = 0;

    END IF;

    UPDATE T006

    LEFT JOIN D009 ON D009_Id=T006_D009_Id

    LEFT JOIN D049 ON D049_Id=D009_D049_Id

                SET T006_Valor_Total_Custo = T006_Valor_Custo_Unitario*T006_Quantidade,

                    T006_Peso_Total = T006_Peso_Unitario*T006_Quantidade,

                    T006_Peso_Bruto_Total = T006_Peso_Bruto*T006_Quantidade,

                    T006_Valor_Total_Despesas=(T006_Valor_Total_Preco*xMultiplicador_Despesa)+xValor_Total_Agregados,

                    T006_Valor_Despesas_Unitario=T006_Valor_Total_Despesas/T006_Quantidade,

                    T006_Valor_Total_Agregados=xValor_Total_Agregados,

                    T006_Valor_Base_IPI=If(T006_Aliquota_IPI>0,(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_IPI='S',T006_Valor_Total_Frete+T006_Valor_Total_Despesas_Acessorias,0))*If(T006_Percentual_Reducao_IPI>0,(T006_Percentual_Reducao_IPI/100),1),0),

                    T006_Valor_IPI=T006_Valor_Base_IPI*(T006_Aliquota_IPI/100),

                    T006_Valor_Total_Custo_Final=(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0)),

                    T006_Valor_Custo_Final_Unitario=T006_Valor_Total_Custo_Final/T006_Quantidade,

                    T006_Valor_Base_ICMS=If(T006_Aliquota_ICMS>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1),0),

                    T006_Valor_Base_ICMS_Oculto=If(T006_Aliquota_ICMS_Oculto>0,T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS_Oculto>0,((100-T006_Percentual_Reducao_ICMS_Oculto)/100),1),0),

                    T006_Valor_Base_ICMS_Desonerado=IF(T006_Aliquota_ICMS_Oculto>0 AND xD006_Flag_Isento_ICMS = 'D',T006_Valor_Total_Custo_Final-IF(T006_Percentual_Reducao_ICMS>0,T006_Valor_Base_ICMS,0),0),

                    T006_Valor_ICMS=T006_Valor_Base_ICMS*(T006_Aliquota_ICMS/100),

                    T006_Valor_ICMS_Oculto=T006_Valor_Base_ICMS_Oculto*(T006_Aliquota_ICMS_Oculto/100),

                    T006_Valor_ICMS_Desonerado=T006_Valor_Base_ICMS_Desonerado*(T006_Aliquota_ICMS_Oculto/100),                    

                    T006_Valor_Base_ICMS_Substituicao=IF(T006_Flag_ST='S',(T006_Valor_Total_Preco+if(xD006_Flag_Somar_Despesas_Base_ST='S',T006_Valor_Total_Despesas,0)+T006_Valor_IPI)*((T006_ST_VA/100)+1),0),

                    T006_Valor_ICMS_Substituicao=(T006_Valor_Base_ICMS_Substituicao*(T006_ST_ICMS_Interno/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=((T006_Valor_Base_ICMS_Substituicao*if(T006_Percentual_Reducao_ICMS_ST>0,((100-T006_Percentual_Reducao_ICMS_ST)/100),1))*(T006_ST_ICMS_Interno/100))-((T006_Valor_Total_Custo_Final*if(T006_Percentual_Reducao_ICMS>0,((100-T006_Percentual_Reducao_ICMS)/100),1))*(T006_ICMS_Inter_Estadual/100)),

                    T006_Valor_ICMS_Substituicao_Retencao=IF(T006_Valor_ICMS_Substituicao_Retencao<0,0,T006_Valor_ICMS_Substituicao_Retencao),

                    T006_Valor_Base_PIS=if(T006_Flag_Isento_PIS='S',0,if(xD006_Flag_Forma_Calculo_PIS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_PIS=if(T006_Flag_Isento_PIS='S',0,T006_Aliquota_PIS),

                    T006_Valor_PIS=if(T006_Aliquota_PIS>0,T006_Valor_Base_PIS*(T006_Aliquota_PIS/100),0),

                    T006_Valor_Base_COFINS=if(T006_Flag_Isento_COFINS='S',0,if(xD006_Flag_Forma_Calculo_COFINS='L',T006_Valor_Total_Preco-T006_Valor_Total_Custo,T006_Valor_Total_Preco)),

                    T006_Aliquota_COFINS=if(T006_Flag_Isento_COFINS='S',0,T006_Aliquota_COFINS),

                    T006_Valor_COFINS=if(T006_Aliquota_COFINS>0,T006_Valor_Base_COFINS*(T006_Aliquota_COFINS/100),0),

                    T006_Aliquota_IRPJ=if(T006_Flag_Isento_IRPJ='S',0,T006_Aliquota_IRPJ),

                    T006_Aliquota_CSLL=if(T006_Flag_Isento_CSLL='S',0,T006_Aliquota_CSLL),

                    T006_Valor_Base_IRPJ=T006_Valor_Total_Preco,

                    T006_Valor_IRPJ=if(T006_Aliquota_IRPJ>0,T006_Valor_Base_IRPJ*(T006_Aliquota_IRPJ/100),0),

                    T006_Valor_Base_CSLL=T006_Valor_Total_Preco,

                    T006_Valor_CSLL=if(T006_Aliquota_CSLL>0,T006_Valor_Base_CSLL*(T006_Aliquota_CSLL/100),0),

                    T006_Valor_ICMS_Credito=if(xT134_Id<=0 or xT134_Id='' or ifnull(xT134_Id,0)<=0,T006_Valor_ICMS_Credito,If(T006_Aliquota_ICMS_Credito>0,(T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))-((T006_Valor_Total_Custo_Final+if(xD006_Flag_Somar_IPI_Base_ICMS='S',T006_Valor_IPI,0))*if(xT134_Reducao_Base_ICMS>0,(xT134_Reducao_Base_ICMS/100),1)),0)*(T006_Aliquota_ICMS_Credito/100)),

                    T006_Total_Cubagem = IFNULL(T006_Cubagem_Unitaria,0) * IFNULL(T006_Quantidade,0),

                    T006_Valor_Trib_Transparencia=IFNULL(T006_Valor_Total_Preco,0)*(IFNULL(T006_Percentual_Trib_Transparencia,0)/100),

                    T006_IPV=(T006_Valor_Preco_Unitario-

                              IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                              IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0))/T006_Valor_Custo_Unitario,

                    T006_Percentual_Margem=round((((T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0))-T006_Valor_Custo_Unitario)/

                              (T006_Valor_Preco_Unitario-

                                IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T006_Valor_ICMS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(T006_Valor_PIS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(T006_Valor_COFINS/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(T006_Valor_IRPJ/T006_Quantidade,0), 0)-

                                IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(T006_Valor_CSLL/T006_Quantidade,0), 0)))*100,2),

                    T006_Valor_Lucro=round((T006_Valor_Total_Custo*T006_IPV)-(T006_Valor_Total_Custo*T006_IPV_Sem_Lucro),2),

                    T006_Valor_Total_Desconto=IF(IFNULL(D049_Flag_Tipo,'') != 'CP' OR xC031_Desabilitar_Compra_Emergencia='S' OR (T006_Quantidade_Estoque+T006_Quantidade_OC) >= T006_Quantidade OR T006_T219_Id > 0 OR T006_T225_Id > 0, T006_Valor_Desconto_Unitario*T006_Quantidade, 0)

              WHERE T006_Id=xT006_Id;

    CALL T005_Gravar_Totalizacao_3(xT005_Id);

END */$$
DELIMITER ;

/* Procedure structure for procedure `T007_Gravar_Totalizacao_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `T007_Gravar_Totalizacao_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T007_Gravar_Totalizacao_3`(xT007_Id int(11))
BEGIN

    DECLARE xValor_Total_Custo DECIMAL(20,2);

    DECLARE xValor_Total_Preco DECIMAL(20,2);

    DECLARE xValor_Total_Custo_Final DECIMAL(20,2);

    DECLARE xValor_Total_Produtos DECIMAL(20,2);

    DECLARE xValor_Total_Servicos DECIMAL(20,2);

    DECLARE xValor_Total_Produtos_Sem_Desconto DECIMAL(20,2);

    DECLARE xValor_Base_ICMS DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Sem_Reducao DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Diferido DECIMAL(20,2);

    DECLARE xValor_ICMS DECIMAL(20,2);

    DECLARE xValor_ICMS_Desonerado DECIMAL(20,2);

    DECLARE xValor_Base_IPI DECIMAL(20,2);

    DECLARE xValor_IPI DECIMAL(20,2);

    DECLARE xValor_Total_II DECIMAL(19,2) DEFAULT 0;

    DECLARE xValor_Base_ICMS_Impresso DECIMAL(20,2);

    DECLARE xValor_Base_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_ICMS_Substituicao_Retencao DECIMAL(20,2) DEFAULT 0;

    DECLARE xValor_PIS DECIMAL(10,2) DEFAULT 0;

    DECLARE xValor_COFINS DECIMAL(10,2) DEFAULT 0;

    DECLARE xPeso_Total DECIMAL(20,3) DEFAULT 0;

    DECLARE xPeso_Total_Bruto DECIMAL(20,3) DEFAULT 0;

    DECLARE xValor_Total_Desconto DECIMAL(15,2) DEFAULT 0;

    DECLARE xValor_Total_Cubagem DECIMAL(10,3) DEFAULT 0;

    DECLARE xValor_Trib_Transparencia DECIMAL(15,2) DEFAULT 0;

    DECLARE xValor_Base_ICMS_Interno DECIMAL(14,2) DEFAULT 0;

    DECLARE xValor_Base_ICMS_Inter_Estadual DECIMAL(14,2) DEFAULT 0;

    DECLARE xValor_ICMS_Interno DECIMAL(14,2) DEFAULT 0;

    DECLARE xValor_ICMS_Inter_Estadual DECIMAL(14,2) DEFAULT 0;

    DECLARE xC004_Id int(10);

    DECLARE xC031_Somar_ICMS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_PIS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_COFINS_Preco_Venda varchar(1);

    DECLARE xC031_Somar_IRPJ_Preco_Venda varchar(1);

    DECLARE xC031_Somar_CSLL_Preco_Venda varchar(1);

    DECLARE xValor_IRPJ DECIMAL(10,2);

    DECLARE xValor_Base_IRPJ DECIMAL(10,2);

    DECLARE xValor_CSLL DECIMAL(10,2);

    DECLARE xValor_Base_CSLL DECIMAL(10,2);



    SELECT sum(T008_Valor_Total_Custo),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco),

           sum(T008_Valor_Total_Preco_Sem_Desconto),

           sum(T008_Valor_Total_Custo_Final),

           sum(round(T008_Valor_Base_ICMS,2)),

           sum(T008_Valor_Base_ICMS_Sem_Reducao),

           sum(T008_Valor_Base_ICMS_Diferido),

           sum(T008_Valor_ICMS),

           sum(T008_Valor_ICMS_Desonerado),

           sum(T008_Valor_Base_IPI),

           sum(T008_Valor_IPI),

           sum(T008_Valor_Base_ICMS_Impresso),

           sum(T008_Valor_Base_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao),

           sum(T008_Valor_ICMS_Substituicao_Retencao),

           sum(T008_Peso_Total),

           sum(T008_Peso_Bruto_Total),

           sum(T008_Valor_Total_Imposto_Importacao),

           sum(T008_Valor_COFINS),

           sum(T008_Valor_PIS),

           sum(T008_Valor_Total_Desconto),

           sum(T008_Total_Cubagem),

           sum(T008_Valor_Base_ICMS_Interno),

           sum(T008_Valor_Base_ICMS_Inter_Estadual),

           sum(T008_Valor_ICMS_Interno),

           sum(T008_Valor_ICMS_Inter_Estadual),

           sum(T008_Valor_Trib_Transparencia),

           sum(T008_Valor_IRPJ),

           sum(T008_Valor_Base_IRPJ),

           sum(T008_Valor_CSLL),

           sum(T008_Valor_Base_CSLL)

      INTO xValor_Total_Custo,

           xValor_Total_Produtos,

           xValor_Total_Preco,

           xValor_Total_Produtos_Sem_Desconto,

           xValor_Total_Custo_Final,

           xValor_Base_ICMS,

           xValor_Base_ICMS_Sem_Reducao,

           xValor_Base_ICMS_Diferido,

           xValor_ICMS,

           xValor_ICMS_Desonerado,

           xValor_Base_IPI,

           xValor_IPI,

           xValor_Base_ICMS_Impresso,

           xValor_Base_ICMS_Substituicao,

           xValor_ICMS_Substituicao,

           xValor_ICMS_Substituicao_Retencao,

           xPeso_Total,

           xPeso_Total_Bruto,

           xValor_Total_II,

           xValor_COFINS,

           xValor_PIS,

           xValor_Total_Desconto,

           xValor_Total_Cubagem,

           xValor_Base_ICMS_Interno,

           xValor_Base_ICMS_Inter_Estadual,

           xValor_ICMS_Interno,

           xValor_ICMS_Inter_Estadual,

           xValor_Trib_Transparencia,

           xValor_IRPJ,

           xValor_Base_IRPJ,

           xValor_CSLL,

           xValor_Base_CSLL

           FROM T008

           WHERE T008_T007_Id=xT007_Id;

      

    SELECT sum(T203_Valor_Unitario)

      INTO xValor_Total_Servicos

      FROM T203

      WHERE T203_T007_Id=xT007_Id;

    

    SELECT T007_C004_Id

      INTO xC004_Id     

      FROM T007

     WHERE T007_Id=xT007_Id;



    SELECT C031_Valor INTO xC031_Somar_ICMS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarICMSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_PIS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarPISPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_COFINS_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCOFINSPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_IRPJ_Preco_Venda FROM C031 WHERE C031_Campo = 'somarIRPJPrecoVenda' AND C031_C004_Id = xC004_Id;

    SELECT C031_Valor INTO xC031_Somar_CSLL_Preco_Venda FROM C031 WHERE C031_Campo = 'somarCSLLPrecoVenda' AND C031_C004_Id = xC004_Id;



    UPDATE T007 SET T007_Valor_Total_Custo=xValor_Total_Custo,

                    T007_Valor_Total_Produtos=xValor_Total_Produtos,

                    T007_Valor_Total_Servicos=xValor_Total_Servicos,

                    T007_Valor_Total_Produtos_Sem_Desconto = xValor_Total_Produtos_Sem_Desconto,

                    T007_Valor_Total_Preco=xValor_Total_Preco,

                    T007_Valor_Total_Custo_Final=xValor_Total_Custo_Final-T007_Valor_Desconto,

                    T007_Valor_Total_Base_ICMS_Sem_Reducao=xValor_Base_ICMS_Sem_Reducao,

                    T007_Valor_Total_Base_ICMS=xValor_Base_ICMS,

                    T007_Valor_Total_Base_ICMS_Diferido=xValor_Base_ICMS_Diferido,

                    T007_Valor_Total_Base_ICMS_Impresso=xValor_Base_ICMS_Impresso,

                    T007_Valor_Total_ICMS=xValor_ICMS,

                    T007_Valor_Total_ICMS_Desonerado=IFNULL(xValor_ICMS_Desonerado,0),

                    T007_Valor_Total_Base_IPI=xValor_Base_IPI,

                    T007_Valor_Total_IPI=xValor_IPI,

                    T007_Valor_Total_Imposto_Importacao=xValor_Total_II,

                    T007_Valor_ISS=if(T007_Aliquota_ISS>0,T007_Valor_Mao_Obra*(T007_Aliquota_ISS/100),0),

                    T007_IPV=if(T007_Valor_Total_Custo>0,(T007_Valor_Total_Produtos-

                                     IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T007_Valor_Total_ICMS,0), 0)-

                                     IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-

                                     IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-

                                     IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-

                                     IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))/T007_Valor_Total_Custo,0),

                    T007_Percentual_Margem=round((((T007_Valor_Total_Produtos-

                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T007_Valor_Total_ICMS,0), 0)-

                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-

                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-

                                            IF(xC031_Somar_IRPJ_Preco_Venda   = 'S', IFNULL(xValor_IRPJ,0), 0)-

                                            IF(xC031_Somar_CSLL_Preco_Venda   = 'S', IFNULL(xValor_CSLL,0), 0))-T007_Valor_Total_Custo)/

                                          (T007_Valor_Total_Produtos-

                                            IF(xC031_Somar_ICMS_Preco_Venda   = 'S', IFNULL(T007_Valor_Total_ICMS,0), 0)-

                                            IF(xC031_Somar_PIS_Preco_Venda    = 'S', IFNULL(xValor_PIS,0), 0)-

                                            IF(xC031_Somar_COFINS_Preco_Venda = 'S', IFNULL(xValor_COFINS,0), 0)-

                                            IF(xC031_Somar_IRPJ_Preco_Venda = 'S', IFNULL(xValor_IRPJ,0), 0)-

                                            IF(xC031_Somar_CSLL_Preco_Venda = 'S', IFNULL(xValor_CSLL,0), 0)))*100,2),

                    T007_Total_Peso=xPeso_Total,

                    T007_Total_Peso_Bruto=xPeso_Total_Bruto,

                    T007_IPV_sem_icms=T007_IPV_Medio(xT007_Id,2),

                    T007_Valor_Base_ICMS_Substituicao=xValor_Base_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao=xValor_ICMS_Substituicao,

                    T007_Valor_ICMS_Substituicao_Retencao=ifnull(xValor_ICMS_Substituicao_Retencao,0.00),

                    T007_Valor_Base_ICMS_Interno=ifnull(xValor_Base_ICMS_Interno,0),

                    T007_Valor_Base_ICMS_Inter_Estadual=ifnull(xValor_Base_ICMS_Inter_Estadual,0),

                    T007_Valor_ICMS_Interno=ifnull(xValor_ICMS_Interno,0),

                    T007_Valor_ICMS_Inter_Estadual=ifnull(xValor_ICMS_Inter_Estadual,0),

                    T007_Valor_Total_COFINS=xValor_COFINS,

                    T007_Valor_Total_PIS=xValor_PIS,

                    T007_Valor_Total_Base_IRPJ=xValor_Base_IRPJ,

                    T007_Valor_Total_IRPJ=xValor_IRPJ,

                    T007_Valor_Total_Base_CSLL=xValor_Base_CSLL,

                    T007_Valor_Total_CSLL=xValor_CSLL,

                    T007_Valor_Desconto=xValor_Total_Desconto,

                    T007_Valor_Total_Trib_Transparencia=xValor_Trib_Transparencia,

                    T007_Valor_Total=T007_Valor_Total_Produtos+

                                     T007_Valor_Total_Servicos+

                                     T007_Valor_Mao_Obra+

                                     T007_Valor_Despesas_Acessorias+

                                     T007_Valor_ICMS_Substituicao_Retencao+

                                     T007_Valor_Total_IPI+

                                     T007_Valor_Seguro+

                                     T007_Valor_Frete-

                                     T007_Valor_Desconto-

                                     IFNULL(T007_Valor_Total_ICMS_Desonerado,0),

                    T007_Total_Cubagem=IFNULL(xValor_Total_Cubagem,0)

              WHERE T007_Id=xT007_Id and T007_Flag_Calcular='S';

    -- SO FAZ OS CALCULOS DA NOTA SE FOR UMA NOTA NORMAL (T007_Flag_Finalidade_NFe=1)

    UPDATE T007 SET T007_Peso_Bruto = xPeso_Total_Bruto,

                    T007_Peso_Liquido = xPeso_Total

                WHERE T007_Id=xT007_Id AND T007_Flag_Totalizar_Peso = 'S';

END */$$
DELIMITER ;

/* Procedure structure for procedure `T007_Gravar_Totalizacao_4` */

/*!50003 DROP PROCEDURE IF EXISTS  `T007_Gravar_Totalizacao_4` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`127.0.0.1` PROCEDURE `T007_Gravar_Totalizacao_4`(xT007_Id int(11))
BEGIN

